insert into hygieia.recipes (id, slug, title_el, title_en, steps_el, steps_en, portions, prep_min, meal_types, image_path) values
  ('ed3e24a9-a71f-32a2-55ce-b79ed2069a7f'::uuid, 'almond-buckwheat-banana-bread', 'Κέικ μπανάνας με αλεύρι αμυγδάλου και φαγόπυρο', 'Banana bread with almond and buckwheat flour', array['Προθερμάνετε τον φούρνο στους 175°C και στρώστε μια φόρμα κέικ με λαδόκολλα.','Λιώστε τις μπανάνες με πιρούνι και χτυπήστε τες με τα αυγά, το λιωμένο λάδι καρύδας και το σιρόπι σφενδάμου.','Αλέστε το φαγόπυρο σε αλεύρι και ανακατέψτε το με το αλεύρι αμυγδάλου, τη σόδα, την κανέλα και το αλάτι· ενώστε με το μείγμα της μπανάνας και προσθέστε τα καρύδια.','Αδειάστε στη φόρμα και ψήστε 50–55 λεπτά, μέχρι η οδοντογλυφίδα να βγαίνει καθαρή.','Αφήστε να κρυώσει 15 λεπτά πριν το κόψετε σε φέτες.']::text[], array['Preheat the oven to 175°C and line a loaf tin with baking paper.','Mash the bananas with a fork and whisk them with the eggs, melted coconut oil and maple syrup.','Grind the buckwheat to flour and mix it with the almond flour, baking soda, cinnamon and salt; fold into the banana mixture and add the walnuts.','Pour into the tin and bake for 50–55 minutes, until a skewer comes out clean.','Let it cool for 15 minutes before slicing.']::text[], 8, 70, array['breakfast','snack']::text[], null),
  ('77435920-350d-c6b3-d308-a0b9b828d6a7'::uuid, 'almond-milk-rice-pudding', 'Ρυζόγαλο με γάλα αμυγδάλου', 'Rice pudding with almond milk', array['Βάλτε το ρύζι με 600 ml από το γάλα αμυγδάλου σε κατσαρόλα και σιγοβράστε 20 λεπτά ανακατεύοντας συχνά.','Διαλύστε το κορν φλάουρ στο υπόλοιπο γάλα, προσθέστε το με τη ζάχαρη και τη βανίλια και μαγειρέψτε 3–4 λεπτά μέχρι να δέσει.','Μοιράστε σε μπολ, πασπαλίστε με κανέλα και αφήστε να κρυώσει.']::text[], array['Put the rice with 600 ml of the almond milk in a saucepan and simmer 20 minutes, stirring often.','Dissolve the cornstarch in the remaining milk, add it with the sugar and vanilla and cook 3–4 minutes until thickened.','Divide into bowls, dust with cinnamon and let cool.']::text[], 3, 35, array['breakfast','snack']::text[], null),
  ('7e5ebaa3-180c-4832-ca8b-8ce1bd9a0360'::uuid, 'apple-almond-butter-cinnamon', 'Φέτες μήλου με αμυγδαλοβούτυρο και κανέλα', 'Apple slices with almond butter and cinnamon', array['Πλύντε τα μήλα και κόψτε τα σε φέτες, αφαιρώντας τα κουκούτσια.','Απλώστε λίγο αμυγδαλοβούτυρο σε κάθε φέτα.','Πασπαλίστε με κανέλα και σερβίρετε αμέσως.']::text[], array['Wash the apples and cut into slices, removing the core.','Spread a little almond butter on each slice.','Dust with cinnamon and serve straight away.']::text[], 2, 5, array['snack']::text[], null),
  ('c801476e-aa30-cb1a-cec6-9532293a39cf'::uuid, 'arakas-latheros-pea-stew', 'Αρακάς λαδερός', 'Arakas latheros — Greek pea stew', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι ψιλοκομμένο για 5 λεπτά.','Προσθέστε τις πατάτες και τα καρότα σε κύβους και ανακατέψτε 3 λεπτά.','Ρίξτε τον αρακά, τον πελτέ διαλυμένο σε 300 ml νερό και τον άνηθο.','Σιγοβράστε 30 λεπτά σκεπασμένο μέχρι να μείνει μόνο το λάδι.']::text[], array['Sauté the chopped onion in the olive oil for 5 minutes.','Add the diced potatoes and carrots and stir for 3 minutes.','Add the peas, the tomato paste dissolved in 300 ml water and the dill.','Simmer, covered, for 30 minutes until only the oil remains.']::text[], 4, 45, array['lunch','dinner']::text[], null),
  ('6b5e96e6-bc89-b395-2f0a-6ce938771c7c'::uuid, 'avocado-toast-whole-wheat', 'Τοστ ολικής με αβοκάντο', 'Whole wheat avocado toast', array['Φρυγανίστε τις φέτες ψωμιού.','Λιώστε το αβοκάντο με πιρούνι μαζί με τον χυμό λεμονιού και το πιπέρι.','Απλώστε το αβοκάντο στο ψωμί.','Κόψτε τα ντοματίνια στη μέση, βάλτε τα από πάνω και πασπαλίστε με νιφάδες τσίλι.']::text[], array['Toast the bread.','Mash the avocado with a fork together with the lemon juice and pepper.','Spread the avocado over the toast.','Halve the cherry tomatoes, put them on top and sprinkle with chilli flakes.']::text[], 1, 10, array['breakfast','snack']::text[], null),
  ('d1c8cb7a-9258-8bc3-312b-38b6fcd8d319'::uuid, 'baked-egg-casserole-zucchini-spinach', 'Αυγά φούρνου με κολοκυθάκι, ντοματίνια και σπανάκι', 'Baked egg casserole with zucchini, cherry tomatoes and spinach', array['Προθερμάνετε τον φούρνο στους 180°C και λαδώστε ένα πυρίμαχο σκεύος.','Τρίψτε το κολοκυθάκι, στύψτε το καλά και απλώστε το στο σκεύος μαζί με το σπανάκι, τα ντοματίνια κομμένα στη μέση και το πράσινο μέρος του φρέσκου κρεμμυδιού.','Χτυπήστε τα αυγά με το ελαιόλαδο, τη ρίγανη, το αλάτι και το πιπέρι και περιχύστε τα λαχανικά.','Ψήστε 25–30 λεπτά μέχρι να πήξει και να ροδίσει η επιφάνεια· κόψτε σε τετράγωνα.']::text[], array['Preheat the oven to 180°C and oil a baking dish.','Grate the zucchini, squeeze it well and spread it in the dish with the spinach, the halved cherry tomatoes and the green part of the spring onion.','Whisk the eggs with the olive oil, oregano, salt and pepper and pour over the vegetables.','Bake 25–30 minutes until set and golden on top; cut into squares.']::text[], 4, 40, array['breakfast','lunch']::text[], null),
  ('e290788c-716f-0343-75be-dea163bb19ad'::uuid, 'baked-polenta-tomato-mozzarella', 'Πολέντα φούρνου με σάλτσα ντομάτας, βασιλικό και μοτσαρέλα', 'Baked polenta with tomato sauce, basil and mozzarella', array['Βράστε το νερό με το αλάτι, ρίξτε το καλαμποκάλευρο σιγά σιγά ανακατεύοντας και μαγειρέψτε 25 λεπτά σε χαμηλή φωτιά· απλώστε σε λαδωμένο ταψί και αφήστε να σφίξει.','Ζεστάνετε 2 κουταλιές ελαιόλαδο, προσθέστε την πασάτα, τη ρίγανη, το πιπέρι και τον μισό βασιλικό και σιγοβράστε 10 λεπτά.','Κόψτε την πολέντα σε κομμάτια, καλύψτε με τη σάλτσα, την παρμεζάνα και τη μοτσαρέλα σε φέτες και περιχύστε με το υπόλοιπο ελαιόλαδο.','Ψήστε στους 200°C για 20 λεπτά μέχρι να λιώσει το τυρί· σερβίρετε με τον υπόλοιπο βασιλικό.']::text[], array['Bring the water to the boil with the salt, pour in the cornmeal slowly while stirring and cook 25 minutes over low heat; spread in an oiled tray and let it set.','Heat 2 tablespoons of olive oil, add the passata, oregano, pepper and half the basil and simmer 10 minutes.','Cut the polenta into pieces, top with the sauce, parmesan and sliced mozzarella and drizzle with the remaining olive oil.','Bake at 200°C for 20 minutes until the cheese melts; serve with the rest of the basil.']::text[], 4, 70, array['lunch','dinner']::text[], null),
  ('54dcecfc-8ad0-46f3-64a0-8a7e3b733a76'::uuid, 'baked-sea-bream-lemon-potatoes', 'Τσιπούρα στον φούρνο με πατάτες λεμονάτες', 'Baked sea bream with lemon potatoes', array['Κόψτε τις πατάτες σε κυδωνάτα κομμάτια και απλώστε τες σε ταψί με το μισό ελαιόλαδο, το σκόρδο, τη ρίγανη και τον χυμό μισού λεμονιού.','Ψήστε στους 200 °C για 30 λεπτά.','Χαράξτε τις τσιπούρες, βάλτε φέτες λεμονιού στην κοιλιά και ακουμπήστε τες πάνω στις πατάτες.','Περιχύστε με το υπόλοιπο λάδι και ψήστε άλλα 25 λεπτά.','Σερβίρετε με ψιλοκομμένο μαϊντανό.']::text[], array['Cut the potatoes into wedges and spread in a tray with half the olive oil, the garlic, oregano and juice of half a lemon.','Bake at 200 °C for 30 minutes.','Score the sea bream, tuck lemon slices into the cavity and lay the fish on the potatoes.','Drizzle with the remaining oil and bake for another 25 minutes.','Serve with chopped parsley.']::text[], 2, 70, array['lunch','dinner']::text[], null),
  ('fb8f2a09-076f-3066-1af0-cb8390578346'::uuid, 'bamies-okra-tomato-stew', 'Μπάμιες λαδερές', 'Bamies — okra in tomato and olive oil', array['Καθαρίστε τα κοτσάνια από τις μπάμιες, ραντίστε τες με το ξίδι και αφήστε τες 30 λεπτά στον ήλιο ή σε ζεστό μέρος.','Σοτάρετε στο ελαιόλαδο το κρεμμύδι ψιλοκομμένο για 5 λεπτά.','Προσθέστε τις ντομάτες και τον μαϊντανό και σιγοβράστε 10 λεπτά.','Ρίξτε τις μπάμιες, κουνήστε την κατσαρόλα αντί να ανακατέψετε και σιγοβράστε 35 λεπτά.']::text[], array['Trim the okra stems, sprinkle with the vinegar and leave for 30 minutes in the sun or a warm spot.','Sauté the chopped onion in the olive oil for 5 minutes.','Add the tomatoes and parsley and simmer for 10 minutes.','Add the okra, shake the pan instead of stirring, and simmer for 35 minutes.']::text[], 4, 85, array['lunch','dinner']::text[], null),
  ('7d665794-dc11-a577-fffa-a966b44ea3e8'::uuid, 'banana-oat-pancakes', 'Τηγανίτες βρώμης με μπανάνα', 'Banana oat pancakes', array['Αλέστε τη βρώμη στο μπλέντερ μέχρι να γίνει αλεύρι.','Προσθέστε τις μπανάνες, τα αυγά, το μπέικιν πάουντερ και την κανέλα και χτυπήστε μέχρι να ομογενοποιηθούν.','Αλείψτε αντικολλητικό τηγάνι με λίγο ελαιόλαδο και ζεστάνετε σε μέτρια φωτιά.','Ρίξτε μια κουταλιά σούπας ζύμη για κάθε τηγανίτα και ψήστε 2 λεπτά από κάθε πλευρά.','Σερβίρετε με μια κουταλιά ελαφρύ γιαούρτι.']::text[], array['Blitz the oats in a blender until they turn into flour.','Add the bananas, eggs, baking powder and cinnamon and blend until smooth.','Brush a non-stick pan with a little olive oil and heat over medium heat.','Drop a tablespoon of batter per pancake and cook 2 minutes on each side.','Serve with a spoonful of light yoghurt.']::text[], 2, 20, array['breakfast']::text[], null),
  ('244a0653-7d12-53c8-d8d2-776c958305b9'::uuid, 'beef-vegetable-chili-no-beans', 'Τσίλι μοσχαριού με λαχανικά (χωρίς φασόλια)', 'Beef and vegetable chili (no beans)', array['Σοτάρετε το κρεμμύδι, το σκόρδο και τις πιπεριές στο ελαιόλαδο 5 λεπτά.','Προσθέστε τον κιμά και τσιγαρίστε τον μέχρι να ροδίσει, σπάζοντας τους σβόλους.','Ρίξτε το κύμινο, την πάπρικα, τις νιφάδες τσίλι, τον πελτέ, τις ντομάτες, το κολοκυθάκι σε κύβους και το αλάτι.','Σιγοβράστε 35–40 λεπτά με μισάνοιχτο καπάκι μέχρι να δέσει.']::text[], array['Sauté the onion, garlic and peppers in the olive oil for 5 minutes.','Add the mince and brown it, breaking up the lumps.','Add the cumin, paprika, chilli flakes, tomato paste, tomatoes, diced zucchini and salt.','Simmer 35–40 minutes with the lid ajar until thick.']::text[], 4, 60, array['lunch','dinner']::text[], null),
  ('44a78717-7e47-55ae-d36a-32c865ad7899'::uuid, 'beef-zucchini-ginger-stir-fry-rice', 'Μοσχάρι σοτέ με κολοκυθάκι, τζίντζερ και ρύζι', 'Beef and zucchini stir-fry with ginger and rice', array['Βράστε το ρύζι σύμφωνα με τις οδηγίες.','Κόψτε το μοσχάρι σε λεπτές λωρίδες και αλατοπιπερώστε· ζεστάνετε το ελαιόλαδο σε βαθύ τηγάνι σε πολύ δυνατή φωτιά και σοτάρετε το κρέας 2–3 λεπτά σε δόσεις· βγάλτε το.','Στο ίδιο τηγάνι σοτάρετε το κολοκυθάκι, την πιπεριά, το καρότο σε λεπτές φέτες και το τριμμένο τζίντζερ 4 λεπτά.','Επιστρέψτε το κρέας, προσθέστε το σησαμέλαιο, τις νιφάδες τσίλι και το πράσινο μέρος του φρέσκου κρεμμυδιού, ανακατέψτε 1 λεπτό και σερβίρετε πάνω στο ρύζι.']::text[], array['Cook the rice according to the packet.','Slice the beef into thin strips and season; heat the olive oil in a deep pan over very high heat and sear the beef 2–3 minutes in batches; remove.','In the same pan stir-fry the zucchini, pepper, thinly sliced carrot and grated ginger for 4 minutes.','Return the beef, add the sesame oil, chilli flakes and the green part of the spring onion, toss 1 minute and serve over the rice.']::text[], 4, 35, array['lunch','dinner']::text[], null),
  ('c659d631-de68-d14e-cdfc-2fde476ab34a'::uuid, 'break-the-fast-egg-avocado-feta-plate', 'Πιάτο «πρώτου γεύματος» με αυγά, αβοκάντο, φέτα και ρυζογκοφρέτες', 'Break-the-fast plate with eggs, avocado, feta and rice cakes', array['Βράστε τα αυγά 8 λεπτά, κρυώστε τα και κόψτε τα στη μέση.','Κόψτε το αβοκάντο και την ντομάτα σε φέτες και βάλτε τα στο πιάτο με τη φέτα, τις ελιές και τις ρυζογκοφρέτες.','Περιχύστε με ελαιόλαδο και πασπαλίστε με ρίγανη.']::text[], array['Boil the eggs for 8 minutes, cool and halve them.','Slice the avocado and tomato and arrange on the plate with the feta, olives and rice cakes.','Drizzle with olive oil and sprinkle with oregano.']::text[], 1, 15, array['breakfast','lunch']::text[], null),
  ('cf91ff8e-db90-bd0a-c72c-72bd73ecb702'::uuid, 'briam-baked-summer-vegetables', 'Μπριάμ', 'Briam — Greek baked summer vegetables', array['Κόψτε τις πατάτες, τα κολοκύθια, τη μελιτζάνα και τα κρεμμύδια σε φέτες μισού εκατοστού.','Τρίψτε τις ντομάτες και ανακατέψτε τες με το σκόρδο λιωμένο, τον μαϊντανό, τη ρίγανη και το ελαιόλαδο.','Απλώστε τα λαχανικά σε ταψί και περιχύστε με τη σάλτσα.','Ψήστε στους 190 °C για 75–90 λεπτά μέχρι να μαλακώσουν και να καραμελώσουν στις άκρες.']::text[], array['Slice the potatoes, courgettes, aubergine and onions about half a centimetre thick.','Grate the tomatoes and mix them with the crushed garlic, parsley, oregano and olive oil.','Spread the vegetables in a baking tray and pour over the sauce.','Bake at 190 °C for 75–90 minutes until soft and caramelised at the edges.']::text[], 4, 100, array['lunch','dinner']::text[], null),
  ('19a4a7e0-28bb-327d-0472-e7ba5db2eec3'::uuid, 'buckwheat-banana-pancakes', 'Τηγανίτες φαγόπυρου με μπανάνα', 'Buckwheat pancakes with banana', array['Αλέστε το φαγόπυρο σε μπλέντερ μέχρι να γίνει αλεύρι και ανακατέψτε το με το μπέικιν πάουντερ, την κανέλα και το αλάτι.','Χτυπήστε τα αυγά με το γάλα αμυγδάλου και προσθέστε τα στα στερεά· ανακατέψτε μέχρι να έχετε ένα ομοιογενές χυλό.','Ζεστάνετε λίγο λάδι σε αντικολλητικό τηγάνι και ψήστε τις τηγανίτες 2 λεπτά από κάθε πλευρά, μέχρι να ροδίσουν.','Σερβίρετε με φέτες μπανάνας και λίγο σιρόπι σφενδάμου.']::text[], array['Blitz the buckwheat in a blender until it becomes flour, then mix it with the baking powder, cinnamon and salt.','Whisk the eggs with the almond milk and add to the dry ingredients; stir until you have a smooth batter.','Heat a little oil in a non-stick pan and cook the pancakes for 2 minutes per side until golden.','Serve topped with banana slices and a little maple syrup.']::text[], 2, 20, array['breakfast']::text[], null),
  ('a4b615ae-d9a4-b2f7-e7c5-e5cef2e93728'::uuid, 'buckwheat-beetroot-walnut-salad', 'Σαλάτα φαγόπυρου με ψητό παντζάρι, καρύδια και φέτα', 'Buckwheat salad with roasted beetroot, walnuts and feta', array['Τυλίξτε τα παντζάρια σε αλουμινόχαρτο και ψήστε στους 200°C για 45 λεπτά· ξεφλουδίστε και κόψτε σε κύβους.','Βράστε το φαγόπυρο σε αλατισμένο νερό 10–12 λεπτά, στραγγίστε και αφήστε να κρυώσει.','Ανακατέψτε το φαγόπυρο με το παντζάρι, το κρεμμύδι σε λεπτές φέτες, τη ρόκα και τα καρύδια.','Περιχύστε με ελαιόλαδο και βαλσάμικο, πιπερώστε και θρυμματίστε τη φέτα από πάνω.']::text[], array['Wrap the beetroots in foil and roast at 200°C for 45 minutes; peel and dice.','Cook the buckwheat in salted water 10–12 minutes, drain and let cool.','Toss the buckwheat with the beetroot, thinly sliced onion, rocket and walnuts.','Dress with olive oil and balsamic, season with pepper and crumble the feta over.']::text[], 4, 60, array['lunch','dinner']::text[], null),
  ('b56ab300-57cb-6d58-cb1d-982ddca979f5'::uuid, 'buckwheat-chia-seeded-bread', 'Ψωμί φαγόπυρου με τσία και ηλιόσπορους (χωρίς γλουτένη)', 'Buckwheat and chia seeded bread (gluten-free)', array['Αλέστε το φαγόπυρο σε αλεύρι και ανακατέψτε το με το ψύλλιο, τους σπόρους τσία, τους ηλιόσπορους, το μπέικιν πάουντερ και το αλάτι.','Προσθέστε το νερό, το ελαιόλαδο και το ξίδι, ανακατέψτε καλά και αφήστε 10 λεπτά να φουσκώσει το ψύλλιο.','Αδειάστε σε λαδωμένη φόρμα και ψήστε στους 190°C για 55–60 λεπτά.','Αφήστε να κρυώσει εντελώς πριν το κόψετε, αλλιώς θρυμματίζεται.']::text[], array['Grind the buckwheat to flour and mix it with the psyllium, chia seeds, sunflower seeds, baking powder and salt.','Add the water, olive oil and vinegar, mix well and leave 10 minutes for the psyllium to swell.','Pour into an oiled loaf tin and bake at 190°C for 55–60 minutes.','Cool completely before slicing or it will crumble.']::text[], 10, 80, array['breakfast','snack']::text[], null),
  ('269a8a53-a329-17b5-f162-7a575a9ed71e'::uuid, 'carrot-ginger-rice-soup', 'Σούπα καρότου με τζίντζερ, ρύζι και γάλα καρύδας', 'Carrot, ginger and rice soup with coconut milk', array['Σοτάρετε το πράσινο μέρος του φρέσκου κρεμμυδιού και το τριμμένο τζίντζερ στο ελαιόλαδο για 2 λεπτά.','Προσθέστε τα καρότα σε ροδέλες, το ρύζι, τον κουρκουμά, το αλάτι και το νερό και σιγοβράστε 25 λεπτά μέχρι να μαλακώσουν.','Πολτοποιήστε με ραβδομπλέντερ, προσθέστε το γάλα καρύδας και τον χυμό λεμονιού και ζεστάνετε ξανά.','Σερβίρετε με πιπέρι και ψιλοκομμένο κόλιανδρο.']::text[], array['Sauté the green part of the spring onion and the grated ginger in the olive oil for 2 minutes.','Add the sliced carrots, rice, turmeric, salt and water and simmer 25 minutes until soft.','Blend with a stick blender, add the coconut milk and lemon juice and reheat.','Serve with pepper and chopped coriander.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('d0b212e0-03a7-d7f7-6223-2bdfdb5b0c5f'::uuid, 'chia-pudding-coconut-strawberry', 'Πουτίγκα τσία με καρύδα και φράουλες', 'Chia pudding with coconut and strawberries', array['Ανακατέψτε σε βάζο τους σπόρους τσία με το γάλα αμυγδάλου, το γάλα καρύδας, το σιρόπι σφενδάμου και τη βανίλια.','Ανακατέψτε ξανά μετά από 10 λεπτά για να μη σβολιάσει και αφήστε στο ψυγείο τουλάχιστον 4 ώρες ή όλη νύχτα.','Σερβίρετε με κομμένες φράουλες και ακτινίδιο.']::text[], array['In a jar, stir the chia seeds with the almond milk, coconut milk, maple syrup and vanilla.','Stir again after 10 minutes so it does not clump, then chill for at least 4 hours or overnight.','Serve topped with sliced strawberries and kiwi.']::text[], 2, 10, array['breakfast','snack']::text[], null),
  ('b5c0d353-5b8b-db9f-cd00-9bba4c4643f3'::uuid, 'chicken-avocado-orange-salad', 'Σαλάτα με κοτόπουλο, αβοκάντο, πορτοκάλι και καρύδια', 'Chicken, avocado and orange salad with walnuts', array['Αλατοπιπερώστε το κοτόπουλο και ψήστε το σε αντικολλητικό τηγάνι με 1 κουταλιά ελαιόλαδο 6–7 λεπτά από κάθε πλευρά· αφήστε το 5 λεπτά και κόψτε το σε φέτες.','Χτυπήστε το υπόλοιπο ελαιόλαδο με τον χυμό λεμονιού και τη μουστάρδα.','Στρώστε το μαρούλι σε πιατέλα με τις φέτες πορτοκαλιού, το αβοκάντο, το κρεμμύδι και το κοτόπουλο· περιχύστε με τη σάλτσα και πασπαλίστε με καρύδια.']::text[], array['Season the chicken and cook it in a non-stick pan with 1 tablespoon of olive oil 6–7 minutes per side; rest 5 minutes and slice.','Whisk the remaining olive oil with the lemon juice and mustard.','Lay the lettuce on a platter with the orange segments, avocado, onion and chicken; drizzle with the dressing and scatter the walnuts over.']::text[], 4, 30, array['lunch','dinner']::text[], null),
  ('dfcf94b9-a63e-a97e-f6d3-903910edc24c'::uuid, 'chicken-coconut-curry-rice', 'Κάρι κοτόπουλου με γάλα καρύδας, σπανάκι και ρύζι μπασμάτι', 'Chicken coconut curry with spinach and basmati rice', array['Σοτάρετε το κρεμμύδι, το σκόρδο και το τζίντζερ στο ελαιόλαδο 5 λεπτά, προσθέστε το κάρι σε σκόνη και ανακατέψτε 1 λεπτό.','Προσθέστε το κοτόπουλο κομμένο σε κομμάτια και σοτάρετε μέχρι να αλλάξει χρώμα.','Ρίξτε τις ντομάτες, το γάλα καρύδας και το αλάτι και σιγοβράστε 20 λεπτά· στο μεταξύ βράστε το ρύζι.','Ρίξτε το σπανάκι να μαραθεί, σερβίρετε πάνω στο ρύζι και πασπαλίστε με κόλιανδρο.']::text[], array['Sauté the onion, garlic and ginger in the olive oil for 5 minutes, add the curry powder and stir 1 minute.','Add the chicken cut into chunks and sauté until it changes colour.','Add the tomatoes, coconut milk and salt and simmer 20 minutes; meanwhile cook the rice.','Wilt in the spinach, serve over the rice and scatter with coriander.']::text[], 4, 45, array['dinner']::text[], null),
  ('f034be05-b4e2-a734-ab78-d39c1a60f165'::uuid, 'chickpea-salad-lemon-parsley', 'Ρεβιθοσαλάτα με λεμόνι και μαϊντανό', 'Chickpea salad with lemon and parsley', array['Μουλιάστε τα ρεβίθια από το προηγούμενο βράδυ και βράστε τα 60 λεπτά μέχρι να μαλακώσουν· στραγγίστε και αφήστε να κρυώσουν.','Κόψτε τα ντοματίνια στη μέση, το αγγούρι σε κύβους και το κρεμμύδι σε λεπτές φέτες.','Ανακατέψτε τα ρεβίθια με τα λαχανικά και τον μαϊντανό ψιλοκομμένο.','Περιχύστε με τον χυμό του λεμονιού, το ελαιόλαδο και το κύμινο και ανακατέψτε.']::text[], array['Soak the chickpeas overnight and boil for 60 minutes until tender; drain and cool.','Halve the cherry tomatoes, dice the cucumber and slice the onion thinly.','Toss the chickpeas with the vegetables and the chopped parsley.','Dress with the lemon juice, olive oil and cumin and toss again.']::text[], 2, 75, array['lunch','dinner']::text[], null),
  ('93fc875a-9299-50bf-b639-9bb244eaba47'::uuid, 'dakos-cretan-rusk-salad', 'Ντάκος Κρητικός', 'Dakos — Cretan barley rusk salad', array['Βρέξτε ελαφρά τα παξιμάδια με νερό και βάλτε τα σε πιάτα.','Τρίψτε τις ντομάτες και απλώστε τες πάνω στα παξιμάδια.','Θρυμματίστε τη φέτα από πάνω και προσθέστε τις ελιές.','Περιχύστε με το ελαιόλαδο και πασπαλίστε με ρίγανη.']::text[], array['Moisten the rusks lightly with water and put them on plates.','Grate the tomatoes and spread them over the rusks.','Crumble the feta over the top and add the olives.','Pour over the olive oil and sprinkle with oregano.']::text[], 2, 10, array['lunch','snack']::text[], null),
  ('d205903b-5852-74f6-9d38-87ace8397e8c'::uuid, 'date-oat-energy-balls', 'Ενεργειακές μπάλες με χουρμάδες και βρώμη', 'Date and oat energy balls', array['Αφαιρέστε τα κουκούτσια από τους χουρμάδες και χτυπήστε τους στο μπλέντερ με τα αμύγδαλα μέχρι να γίνουν πάστα.','Προσθέστε τη βρώμη, το κακάο και το ταχίνι και χτυπήστε ξανά μέχρι να δέσει το μείγμα.','Πλάστε 12 μπαλίτσες και βάλτε τες στο ψυγείο 30 λεπτά να σφίξουν.']::text[], array['Pit the dates and blitz them with the almonds in a food processor until a paste forms.','Add the oats, cocoa and tahini and blitz again until the mixture holds together.','Roll into 12 balls and chill for 30 minutes to firm up.']::text[], 6, 45, array['snack']::text[], null),
  ('610ec0ea-2649-668f-6b2c-2e5a2107f668'::uuid, 'date-walnut-cocoa-energy-balls', 'Μπαλίτσες ενέργειας με χουρμάδες, καρύδια και κακάο', 'Date, walnut and cocoa energy balls', array['Αφαιρέστε τα κουκούτσια από τους χουρμάδες και χτυπήστε τους στο μπλέντερ με τα καρύδια, το κακάο, την κανέλα και το αλάτι μέχρι να γίνουν μια κολλώδης μάζα.','Πλάστε οκτώ μπαλίτσες με βρεγμένα χέρια.','Κυλήστε τες στην καρύδα και κρατήστε τες στο ψυγείο σε κλειστό δοχείο.']::text[], array['Pit the dates and blitz them in a food processor with the walnuts, cocoa, cinnamon and salt until the mixture becomes a sticky mass.','Roll into eight balls with damp hands.','Roll in the coconut and keep in the fridge in a sealed container.']::text[], 8, 15, array['snack']::text[], null),
  ('05f58c74-52d0-7326-fcf0-fd24d21c9b61'::uuid, 'fakes-lentil-soup', 'Φακές σούπα', 'Fakes — Greek lentil soup', array['Πλύντε τις φακές και βράστε τες 5 λεπτά· στραγγίστε.','Σοτάρετε στο μισό ελαιόλαδο το κρεμμύδι, το σκόρδο και το καρότο ψιλοκομμένα.','Ρίξτε τις φακές, τις ντομάτες, τη δάφνη και νερό να τις σκεπάζει κατά 2 δάχτυλα.','Σιγοβράστε 30–40 λεπτά μέχρι να μαλακώσουν.','Τελειώστε με το υπόλοιπο ελαιόλαδο και το ξίδι και σερβίρετε.']::text[], array['Rinse the lentils and boil them for 5 minutes; drain.','Sauté the chopped onion, garlic and carrot in half the olive oil.','Add the lentils, tomatoes, bay leaves and water to cover by about 3 cm.','Simmer for 30–40 minutes until tender.','Finish with the remaining olive oil and the vinegar and serve.']::text[], 4, 50, array['lunch','dinner']::text[], null),
  ('a6962179-e961-70fe-ba45-5be9156c6ae3'::uuid, 'fasolada-white-bean-soup', 'Φασολάδα', 'Fasolada — Greek white bean soup', array['Μουλιάστε τα φασόλια από το προηγούμενο βράδυ, στραγγίστε και βράστε τα 5 λεπτά σε φρέσκο νερό· πετάξτε το νερό.','Ψιλοκόψτε το κρεμμύδι, το καρότο και το σέλερι και σοτάρετέ τα στο μισό ελαιόλαδο.','Προσθέστε τα φασόλια, τις ντομάτες, τον πελτέ, τη δάφνη και νερό να τα σκεπάζει κατά 3 δάχτυλα.','Σιγοβράστε 60–90 λεπτά μέχρι να μαλακώσουν τα φασόλια και να δέσει η σούπα.','Ρίξτε το υπόλοιπο ελαιόλαδο, τον μαϊντανό και το πιπέρι και σερβίρετε.']::text[], array['Soak the beans overnight, drain, boil for 5 minutes in fresh water and discard that water.','Finely chop the onion, carrot and celery and sauté them in half the olive oil.','Add the beans, tomatoes, tomato paste, bay leaves and water to cover by about 5 cm.','Simmer for 60–90 minutes until the beans are tender and the soup has thickened.','Stir in the remaining olive oil, the parsley and the pepper and serve.']::text[], 4, 100, array['lunch','dinner']::text[], null),
  ('0572678b-c39c-4c0f-73f3-0fc40457c984'::uuid, 'fasolakia-ladera-green-bean-stew', 'Φασολάκια λαδερά', 'Fasolakia — green beans braised in olive oil and tomato', array['Καθαρίστε τα φασολάκια και κόψτε τα στη μέση.','Σοτάρετε στο ελαιόλαδο το κρεμμύδι και το σκόρδο ψιλοκομμένα για 5 λεπτά.','Προσθέστε τα φασολάκια, τις πατάτες σε κομμάτια, τις ντομάτες και τον μαϊντανό.','Σιγοβράστε 45 λεπτά σκεπασμένο μέχρι να μαλακώσουν και να δέσει η σάλτσα.']::text[], array['Top and tail the green beans and halve them.','Sauté the chopped onion and garlic in the olive oil for 5 minutes.','Add the beans, the potatoes in chunks, the tomatoes and the parsley.','Simmer, covered, for 45 minutes until tender and the sauce has thickened.']::text[], 4, 60, array['lunch','dinner']::text[], null),
  ('a37823b8-aec4-f3c0-d5ca-61ba0c7c0d9f'::uuid, 'fava-santorini-yellow-split-pea-puree', 'Φάβα Σαντορίνης', 'Fava — Santorini yellow split pea purée', array['Πλύντε τη φάβα και βάλτε τη σε κατσαρόλα με το κρεμμύδι κομμένο στα τέσσερα και νερό να τη σκεπάζει.','Σιγοβράστε 40–50 λεπτά ξαφρίζοντας, μέχρι να λιώσει.','Πολτοποιήστε με το μισό ελαιόλαδο και τον χυμό του λεμονιού.','Σερβίρετε με ψιλοκομμένο κόκκινο κρεμμύδι και το υπόλοιπο ελαιόλαδο από πάνω.']::text[], array['Rinse the split peas and put them in a pan with the quartered onion and water to cover.','Simmer for 40–50 minutes, skimming, until they fall apart.','Blend with half the olive oil and the lemon juice.','Serve topped with finely chopped red onion and the remaining olive oil.']::text[], 4, 55, array['lunch','dinner','snack']::text[], null),
  ('965157e2-a2e2-2793-a6c3-0a23eef27aa0'::uuid, 'fish-taco-bowls-cabbage-slaw', 'Μπολ «fish taco» με ρύζι, λάχανο και λάιμ', 'Fish taco bowls with rice, cabbage slaw and lime', array['Βράστε το ρύζι σύμφωνα με τις οδηγίες.','Ψιλοκόψτε το λάχανο και τρίψτε το καρότο· ανακατέψτε τα με τη μαγιονέζα, τον χυμό του ενός λάιμ και τον μισό κόλιανδρο.','Αλείψτε τον μπακαλιάρο με 1 κουταλιά ελαιόλαδο, το κύμινο, την πάπρικα, τις νιφάδες τσίλι και το αλάτι και ψήστε τον στο υπόλοιπο ελαιόλαδο 3–4 λεπτά από κάθε πλευρά.','Μοιράστε το ρύζι σε μπολ, βάλτε από πάνω τη σαλάτα λάχανου και το ψάρι σε κομμάτια και σερβίρετε με το δεύτερο λάιμ και τον υπόλοιπο κόλιανδρο.']::text[], array['Cook the rice according to the packet.','Finely shred the cabbage and grate the carrot; toss with the mayonnaise, the juice of one lime and half the coriander.','Rub the cod with 1 tablespoon of olive oil, the cumin, paprika, chilli flakes and salt and cook it in the remaining olive oil 3–4 minutes per side.','Divide the rice between bowls, top with the slaw and the flaked fish and serve with the second lime and the rest of the coriander.']::text[], 4, 35, array['lunch','dinner']::text[], null),
  ('73dea48f-4919-f0d8-8a5d-2b8041e762e1'::uuid, 'fruit-salad-coconut-walnuts', 'Φρουτοσαλάτα με καρύδα, καρύδια και δυόσμο', 'Fruit salad with coconut, walnuts and mint', array['Καθαρίστε τα πορτοκάλια και τα ακτινίδια και κόψτε τα σε κομμάτια μαζί με τις φράουλες και την μπανάνα.','Περιχύστε με τον χυμό του λάιμ και ανακατέψτε απαλά.','Πασπαλίστε με την καρύδα, τα καρύδια και ψιλοκομμένο δυόσμο.']::text[], array['Peel the oranges and kiwis and cut them into pieces with the strawberries and banana.','Squeeze over the lime juice and toss gently.','Sprinkle with the coconut, walnuts and chopped mint.']::text[], 3, 15, array['breakfast','snack']::text[], null),
  ('8aa84943-06a6-bcf2-27ee-5806a19563fc'::uuid, 'gemista-stuffed-tomatoes-peppers', 'Γεμιστά', 'Gemista — rice-stuffed tomatoes and peppers', array['Κόψτε καπάκια από τις ντομάτες και τις πιπεριές και αδειάστε τες· κρατήστε τη σάρκα της ντομάτας.','Σοτάρετε το κρεμμύδι στο μισό ελαιόλαδο, ρίξτε το ρύζι, τη σάρκα της ντομάτας, τα κουκουνάρια και τις σταφίδες και ανακατέψτε 5 λεπτά.','Αποσύρετε και προσθέστε τον μαϊντανό και τον δυόσμο ψιλοκομμένους.','Γεμίστε τα λαχανικά ως τα 3/4, κλείστε με τα καπάκια και βάλτε τις πατάτες κομμένες ανάμεσα.','Περιχύστε με το υπόλοιπο λάδι και λίγο νερό και ψήστε στους 180 °C για 75 λεπτά.']::text[], array['Cut lids off the tomatoes and peppers and hollow them out; keep the tomato flesh.','Sauté the onion in half the olive oil, add the rice, tomato flesh, pine nuts and raisins and stir for 5 minutes.','Take off the heat and add the chopped parsley and mint.','Fill the vegetables three-quarters full, replace the lids and tuck the cut potatoes between them.','Drizzle with the remaining oil and a little water and bake at 180 °C for 75 minutes.']::text[], 4, 110, array['lunch','dinner']::text[], null),
  ('08fd5735-6cd3-4275-dd9b-414a7c6e2f1a'::uuid, 'gigantes-plaki-baked-giant-beans', 'Γίγαντες πλακί', 'Gigantes plaki — baked giant beans in tomato', array['Μουλιάστε τους γίγαντες από το προηγούμενο βράδυ και βράστε τους 40 λεπτά μέχρι να μαλακώσουν ελαφρά.','Σοτάρετε στο μισό ελαιόλαδο το κρεμμύδι, το σκόρδο, το καρότο και το σέλερι ψιλοκομμένα.','Προσθέστε τις ντομάτες και σιγοβράστε 10 λεπτά.','Απλώστε τα φασόλια σε ταψί, ρίξτε τη σάλτσα, το υπόλοιπο λάδι, τον μαϊντανό και τον άνηθο και λίγο νερό.','Ψήστε στους 180 °C για 60 λεπτά μέχρι να ροδίσουν.']::text[], array['Soak the beans overnight and boil them for 40 minutes until just tender.','Sauté the chopped onion, garlic, carrot and celery in half the olive oil.','Add the tomatoes and simmer for 10 minutes.','Spread the beans in a baking dish, pour over the sauce, remaining oil, parsley, dill and a little water.','Bake at 180 °C for 60 minutes until golden.']::text[], 4, 120, array['lunch','dinner']::text[], null),
  ('ce8c43a1-c18f-bd0d-5201-3aad5cb006fc'::uuid, 'greek-yoghurt-honey-walnuts-figs', 'Γιαούρτι με μέλι, καρύδια και σύκα', 'Greek yoghurt with honey, walnuts and figs', array['Βάλτε το γιαούρτι σε ένα μπολ.','Κόψτε τα σύκα στα τέσσερα και ακουμπήστε τα πάνω στο γιαούρτι.','Σπάστε τα καρύδια με τα χέρια και σκορπίστε τα από πάνω.','Περιχύστε με το μέλι και σερβίρετε αμέσως.']::text[], array['Spoon the yoghurt into a bowl.','Quarter the figs and arrange them on the yoghurt.','Break the walnuts with your hands and scatter them over.','Drizzle with the honey and serve straight away.']::text[], 1, 5, array['breakfast','snack']::text[], null),
  ('c4afb386-fe3d-82c3-f9ca-5027e3567b6d'::uuid, 'green-smoothie-spinach-banana', 'Πράσινο σμούθι με σπανάκι και μπανάνα', 'Green smoothie with spinach and banana', array['Πλύντε το σπανάκι και κόψτε το μήλο σε κομμάτια, χωρίς τα κουκούτσια.','Βάλτε στο μπλέντερ το σπανάκι, το μήλο, την μπανάνα, τον λιναρόσπορο και το γάλα βρώμης.','Χτυπήστε 1 λεπτό μέχρι να γίνει λείο και σερβίρετε αμέσως.']::text[], array['Rinse the spinach and cut the apple into chunks, discarding the core.','Put the spinach, apple, banana, flaxseed and oat milk in a blender.','Blend for a minute until smooth and serve at once.']::text[], 1, 5, array['breakfast','snack']::text[], null),
  ('c94906dc-576b-b2f6-ae14-63247605d0e7'::uuid, 'grilled-mackerel-horta-lemon', 'Σκουμπρί στη σχάρα με χόρτα λαδολέμονο', 'Grilled mackerel with horta and lemon', array['Καθαρίστε τα χόρτα και βράστε τα 10 λεπτά σε άφθονο νερό· στραγγίστε.','Χαράξτε τα σκουμπριά και ψήστε τα σε δυνατή σχάρα 5 λεπτά από κάθε πλευρά.','Ανακατέψτε το ελαιόλαδο με τον χυμό του λεμονιού και το σκόρδο λιωμένο.','Σερβίρετε το ψάρι με τα χόρτα και περιχύστε όλα με το λαδολέμονο.']::text[], array['Trim the greens and boil for 10 minutes in plenty of water; drain.','Score the mackerel and grill over high heat for 5 minutes per side.','Whisk the olive oil with the lemon juice and crushed garlic.','Serve the fish with the greens and pour the lemon-oil dressing over everything.']::text[], 2, 35, array['lunch','dinner']::text[], null),
  ('cd605cfb-98e6-9a6f-8005-2c01b6476839'::uuid, 'grilled-sardines-lemon-oregano', 'Σαρδέλες στη σχάρα με λεμόνι και ρίγανη', 'Grilled sardines with lemon and oregano', array['Καθαρίστε τις σαρδέλες, ξεπλύντε και στεγνώστε τες.','Ανακατέψτε το ελαιόλαδο με τον χυμό του λεμονιού, τη ρίγανη και το σκόρδο λιωμένο.','Ψήστε τις σαρδέλες σε δυνατή σχάρα 3 λεπτά από κάθε πλευρά.','Περιχύστε με το λαδολέμονο και σκορπίστε μαϊντανό.']::text[], array['Gut the sardines, rinse and pat dry.','Mix the olive oil with the lemon juice, oregano and crushed garlic.','Grill the sardines over high heat for 3 minutes per side.','Pour over the lemon-oil dressing and scatter with parsley.']::text[], 2, 25, array['lunch','dinner']::text[], null),
  ('88dcc266-aefb-d9fb-d612-4fee6fe5df7f'::uuid, 'halloumi-grilled-vegetable-salad', 'Σαλάτα με ψητό χαλούμι και λαχανικά', 'Grilled halloumi and vegetable salad', array['Κόψτε το κολοκύθι και την πιπεριά σε φέτες και ψήστε τα σε γκριλ ή τηγάνι-σχάρα με λίγο ελαιόλαδο.','Κόψτε το χαλούμι σε φέτες και ψήστε το 2 λεπτά από κάθε πλευρά μέχρι να ροδίσει.','Απλώστε τη ρόκα και τα ντοματίνια κομμένα στη μέση σε πιατέλα.','Βάλτε από πάνω τα λαχανικά και το χαλούμι, περιχύστε με το υπόλοιπο λάδι και το λεμόνι και σκορπίστε δυόσμο.']::text[], array['Slice the courgette and pepper and grill them on a griddle with a little olive oil.','Slice the halloumi and grill for 2 minutes per side until golden.','Spread the rocket and halved cherry tomatoes on a platter.','Top with the vegetables and halloumi, dress with the remaining oil and lemon and scatter mint.']::text[], 2, 25, array['lunch','dinner']::text[], null),
  ('efacacb2-3271-f93b-4c9b-bc42af7481ea'::uuid, 'horiatiki-greek-village-salad', 'Χωριάτικη σαλάτα', 'Horiatiki — Greek village salad', array['Κόψτε τις ντομάτες σε χοντρά κομμάτια και το αγγούρι σε ροδέλες.','Κόψτε το κρεμμύδι και την πιπεριά σε λεπτές φέτες.','Βάλτε όλα τα λαχανικά σε πιατέλα με τις ελιές.','Ακουμπήστε τη φέτα από πάνω, πασπαλίστε με ρίγανη και περιχύστε με το ελαιόλαδο.']::text[], array['Cut the tomatoes into chunky wedges and the cucumber into rounds.','Slice the onion and the pepper thinly.','Put all the vegetables on a platter with the olives.','Lay the feta on top, sprinkle with oregano and pour over the olive oil.']::text[], 2, 10, array['lunch','dinner']::text[], null),
  ('740fb4f0-1102-745b-3acb-107616d94dcf'::uuid, 'hummus-homemade', 'Χούμους σπιτικό', 'Homemade hummus', array['Μουλιάστε τα ρεβίθια 12 ώρες και βράστε τα 60–80 λεπτά μέχρι να μαλακώσουν πολύ· κρατήστε λίγο ζουμί.','Χτυπήστε στο μπλέντερ τα ρεβίθια με το ταχίνι, τον χυμό λεμονιού, το σκόρδο και το κύμινο.','Προσθέστε ζουμί από το βράσιμο μέχρι να γίνει βελούδινο.','Σερβίρετε με το ελαιόλαδο και την πάπρικα από πάνω.']::text[], array['Soak the chickpeas for 12 hours and boil for 60–80 minutes until very soft; keep some cooking water.','Blend the chickpeas with the tahini, lemon juice, garlic and cumin.','Add cooking water until the hummus is silky.','Serve with the olive oil and paprika on top.']::text[], 4, 90, array['snack','lunch']::text[], null),
  ('833fdde4-64b7-8879-3a74-3ff7a461c05a'::uuid, 'imam-bayildi-stuffed-eggplant', 'Ιμάμ μπαϊλντί', 'Imam bayildi — onion-stuffed baked aubergine', array['Κόψτε τις μελιτζάνες στη μέση κατά μήκος, χαράξτε τη σάρκα και ψήστε τες 20 λεπτά στους 200 °C με το μισό ελαιόλαδο.','Σοτάρετε στο υπόλοιπο λάδι τα κρεμμύδια σε φέτες και το σκόρδο μέχρι να μαλακώσουν.','Προσθέστε τις ντομάτες ψιλοκομμένες και τον μαϊντανό και σιγοβράστε 10 λεπτά.','Πιέστε τη σάρκα των μελιτζανών να ανοίξει, γεμίστε με το μείγμα και ψήστε άλλα 30 λεπτά.']::text[], array['Halve the aubergines lengthways, score the flesh and roast for 20 minutes at 200 °C with half the olive oil.','Sauté the sliced onions and garlic in the remaining oil until soft.','Add the chopped tomatoes and parsley and simmer for 10 minutes.','Press the aubergine flesh open, fill with the mixture and bake for another 30 minutes.']::text[], 2, 75, array['lunch','dinner']::text[], null),
  ('e76ff97a-f16d-1613-df4a-a7ea472b84ea'::uuid, 'kolokithokeftedes-zucchini-fritters', 'Κολοκυθοκεφτέδες', 'Kolokithokeftedes — zucchini and feta fritters', array['Τρίψτε τα κολοκύθια, αλατίστε ελαφρά και στύψτε τα πολύ καλά να φύγουν τα υγρά.','Ανακατέψτε με τη φέτα θρυμματισμένη, το αυγό, τα φρέσκα κρεμμυδάκια, τον άνηθο και τον δυόσμο ψιλοκομμένους.','Προσθέστε το αλεύρι σταδιακά μέχρι να πλάθεται το μείγμα.','Πλάστε μικρούς κεφτέδες και ψήστε τους στο ελαιόλαδο 3 λεπτά από κάθε πλευρά.']::text[], array['Grate the courgettes, salt lightly and squeeze very well to remove the liquid.','Mix with the crumbled feta, the egg and the chopped spring onions, dill and mint.','Add the flour gradually until the mixture can be shaped.','Shape into small patties and fry in the olive oil for 3 minutes on each side.']::text[], 4, 40, array['lunch','snack']::text[], null),
  ('405e08af-bb49-0c0d-a5eb-c3fa70ebed47'::uuid, 'lahanorizo-cabbage-rice', 'Λαχανόρυζο', 'Lahanorizo — cabbage and rice', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι και το καρότο ψιλοκομμένα για 5 λεπτά.','Ρίξτε το λάχανο κομμένο σε λωρίδες και ανακατεύετε μέχρι να μαραθεί.','Προσθέστε τον πελτέ, το ρύζι και 500 ml νερό και σιγοβράστε 20 λεπτά.','Σερβίρετε με λεμόνι και ψιλοκομμένο μαϊντανό.']::text[], array['Sauté the chopped onion and carrot in the olive oil for 5 minutes.','Add the shredded cabbage and stir until it wilts.','Add the tomato paste, the rice and 500 ml water and simmer for 20 minutes.','Serve with lemon and chopped parsley.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('4f638597-7be5-e44e-a643-13846b497157'::uuid, 'lemon-chicken-rice-bowl', 'Μπολ με λεμονάτο κοτόπουλο, ρύζι μπασμάτι και καρότο', 'Lemon chicken and basmati rice bowl with carrot', array['Μαρινάρετε το κοτόπουλο κομμένο σε κομμάτια με τον χυμό και το ξύσμα του λεμονιού, το τριμμένο τζίντζερ, τη ρίγανη, το αλάτι και το πιπέρι για 15 λεπτά.','Βράστε το ρύζι μπασμάτι σύμφωνα με τις οδηγίες και κρατήστε το ζεστό.','Ψήστε το κοτόπουλο στο ελαιόλαδο σε δυνατή φωτιά 6–8 λεπτά μέχρι να ροδίσει και να ψηθεί.','Μοιράστε το ρύζι σε μπολ, προσθέστε το κοτόπουλο, το τριμμένο καρότο, το αγγούρι σε φέτες και το πράσινο μέρος του φρέσκου κρεμμυδιού.']::text[], array['Marinate the chicken, cut into chunks, with the lemon juice and zest, grated ginger, oregano, salt and pepper for 15 minutes.','Cook the basmati rice according to the packet and keep warm.','Sear the chicken in the olive oil over high heat 6–8 minutes until golden and cooked through.','Divide the rice between bowls, add the chicken, grated carrot, sliced cucumber and the green part of the spring onion.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('e1133b41-d96a-f470-b28e-cdef14bb710c'::uuid, 'lentil-bolognese-whole-wheat-pasta', 'Μπολονέζ φακής με ζυμαρικά ολικής', 'Lentil bolognese with whole wheat pasta', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι, το καρότο, το σέλερι και το σκόρδο ψιλοκομμένα για 8 λεπτά.','Προσθέστε τις φακές, τις ντομάτες, τη ρίγανη και 500 ml νερό.','Σιγοβράστε 35 λεπτά μέχρι να μαλακώσουν οι φακές και να δέσει η σάλτσα.','Βράστε τα ζυμαρικά, στραγγίστε και σερβίρετε με τη σάλτσα.']::text[], array['Sauté the finely chopped onion, carrot, celery and garlic in the olive oil for 8 minutes.','Add the lentils, tomatoes, oregano and 500 ml water.','Simmer for 35 minutes until the lentils are tender and the sauce has thickened.','Cook the pasta, drain and serve with the sauce.']::text[], 4, 50, array['lunch','dinner']::text[], null),
  ('0705ad37-7b8f-e1a9-8393-001369b119db'::uuid, 'lentil-pasta-tomato-spinach-feta', 'Ζυμαρικά φακής με σάλτσα ντομάτας, σπανάκι και φέτα', 'Lentil pasta with tomato sauce, spinach and feta', array['Σοτάρετε το κρεμμύδι και το σκόρδο στο ελαιόλαδο, προσθέστε τις ντομάτες, τη ρίγανη, τις νιφάδες τσίλι, το αλάτι και το πιπέρι και σιγοβράστε 15 λεπτά.','Βράστε τα ζυμαρικά φακής 1 λεπτό λιγότερο από τις οδηγίες και στραγγίστε.','Ρίξτε το σπανάκι στη σάλτσα να μαραθεί, προσθέστε τα ζυμαρικά και ανακατέψτε.','Σερβίρετε με θρυμματισμένη φέτα και φύλλα βασιλικού.']::text[], array['Sauté the onion and garlic in the olive oil, add the tomatoes, oregano, chilli flakes, salt and pepper and simmer 15 minutes.','Cook the lentil pasta 1 minute short of the packet time and drain.','Wilt the spinach into the sauce, add the pasta and toss.','Serve with crumbled feta and basil leaves.']::text[], 4, 30, array['lunch','dinner']::text[], null),
  ('e6ad4ff6-0774-d500-cde2-d0743879d527'::uuid, 'lentil-salad-roasted-beetroot-walnuts', 'Σαλάτα φακής με ψητό παντζάρι και καρύδια', 'Lentil salad with roasted beetroot and walnuts', array['Τυλίξτε τα παντζάρια σε αλουμινόχαρτο και ψήστε τα 45 λεπτά στους 200 °C· καθαρίστε και κόψτε σε κύβους.','Βράστε τις φακές 20 λεπτά να μείνουν σφιχτές και στραγγίστε.','Ανακατέψτε τις φακές με τα παντζάρια, τη ρόκα και τα καρύδια.','Περιχύστε με το βαλσάμικο και το ελαιόλαδο.']::text[], array['Wrap the beetroot in foil and roast for 45 minutes at 200 °C; peel and dice.','Boil the lentils for 20 minutes so they stay firm and drain.','Toss the lentils with the beetroot, rocket and walnuts.','Dress with the balsamic vinegar and olive oil.']::text[], 2, 60, array['lunch','dinner']::text[], null),
  ('a36e87d1-2319-fb79-5908-e0d959c013f2'::uuid, 'mushroom-spinach-omelette', 'Ομελέτα με μανιτάρια και σπανάκι', 'Mushroom and spinach omelette', array['Κόψτε τα μανιτάρια σε φέτες και σοτάρετέ τα στο μισό ελαιόλαδο μέχρι να ροδίσουν.','Ρίξτε το σπανάκι και ανακατέψτε μέχρι να μαραθεί· βγάλτε τα σε πιάτο.','Χτυπήστε τα αυγά με το πιπέρι και ρίξτε τα στο τηγάνι με το υπόλοιπο λάδι.','Όταν πήξει η βάση, βάλτε τη γέμιση στη μία πλευρά και διπλώστε την ομελέτα.','Σερβίρετε με ψιλοκομμένο μαϊντανό.']::text[], array['Slice the mushrooms and sauté them in half the olive oil until golden.','Add the spinach and stir until wilted; tip onto a plate.','Beat the eggs with the pepper and pour into the pan with the remaining oil.','When the base has set, spoon the filling onto one half and fold the omelette over.','Serve with chopped parsley.']::text[], 1, 15, array['breakfast','dinner']::text[], null),
  ('c1677752-a7e7-3173-9555-e980d0f38b71'::uuid, 'mydopilafo-mussel-rice', 'Μυδοπίλαφο', 'Mydopilafo — mussel rice with dill and lemon', array['Καθαρίστε τα μύδια και πετάξτε όσα μένουν ανοιχτά.','Σοτάρετε στο ελαιόλαδο το κρεμμύδι και το σκόρδο ψιλοκομμένα για 5 λεπτά.','Ρίξτε τα μύδια και το κρασί, σκεπάστε και μαγειρέψτε 4 λεπτά μέχρι να ανοίξουν· βγάλτε τα από τα κελύφη.','Προσθέστε το ρύζι και 350 ml νερό στο ζουμί και σιγοβράστε 18 λεπτά.','Ανακατέψτε με τα μύδια, τον άνηθο και τον χυμό του λεμονιού και σερβίρετε.']::text[], array['Scrub the mussels and discard any that stay open.','Sauté the chopped onion and garlic in the olive oil for 5 minutes.','Add the mussels and wine, cover and cook for 4 minutes until they open; shell them.','Add the rice and 350 ml water to the liquor and simmer for 18 minutes.','Stir in the mussels, dill and lemon juice and serve.']::text[], 2, 45, array['lunch','dinner']::text[], null),
  ('43c025de-3194-54f3-a104-817469ab9d23'::uuid, 'oat-porridge-banana-walnuts', 'Χυλός βρώμης με μπανάνα και καρύδια', 'Oat porridge with banana and walnuts', array['Βάλτε τη βρώμη και το γάλα βρώμης σε κατσαρολάκι σε μέτρια φωτιά.','Ανακατεύετε 4–5 λεπτά μέχρι να πήξει ο χυλός.','Κόψτε την μπανάνα σε ροδέλες και ρίξτε τη μισή μέσα στον χυλό.','Σερβίρετε με την υπόλοιπη μπανάνα, τα καρύδια και κανέλα από πάνω.']::text[], array['Put the oats and oat milk in a small pan over medium heat.','Stir for 4–5 minutes until the porridge thickens.','Slice the banana and stir half of it into the porridge.','Serve topped with the remaining banana, the walnuts and a dusting of cinnamon.']::text[], 1, 10, array['breakfast']::text[], null),
  ('51fa63d7-e277-81b8-288f-48a0632c60e2'::uuid, 'octopus-xydato-vinegar-oregano', 'Χταπόδι ξιδάτο', 'Octopus xydato — with vinegar, oregano and olive oil', array['Βάλτε το χταπόδι σε κατσαρόλα χωρίς νερό, σκεπάστε και σιγοβράστε 45–60 λεπτά στα υγρά του μέχρι να μαλακώσει.','Αφήστε το να κρυώσει και κόψτε το σε μπουκιές.','Ανακατέψτε με το ξίδι, το ελαιόλαδο, τη ρίγανη και το κόκκινο κρεμμύδι σε λεπτές φέτες.','Αφήστε 30 λεπτά να μαριναριστεί και σερβίρετε με μαϊντανό.']::text[], array['Put the octopus in a pan with no water, cover and simmer in its own juices for 45–60 minutes until tender.','Let it cool and cut into bite-sized pieces.','Toss with the vinegar, olive oil, oregano and thinly sliced red onion.','Marinate for 30 minutes and serve with parsley.']::text[], 2, 100, array['lunch','dinner','snack']::text[], null),
  ('ab67ca20-6039-9193-4f4d-313f20063f50'::uuid, 'overnight-oats-apple-cinnamon', 'Βρώμη βραδιάς με μήλο και κανέλα', 'Overnight oats with apple and cinnamon', array['Ανακατέψτε σε βάζο τη βρώμη, το γάλα αμυγδάλου, τους σπόρους τσία και την κανέλα.','Κλείστε το βάζο και αφήστε το στο ψυγείο όλη τη νύχτα.','Το πρωί τρίψτε το μισό μήλο και ανακατέψτε το μέσα.','Σερβίρετε με τις σταφίδες από πάνω.']::text[], array['Mix the oats, almond milk, chia seeds and cinnamon in a jar.','Close the jar and leave it in the fridge overnight.','In the morning, grate half an apple and stir it in.','Serve with the raisins scattered on top.']::text[], 1, 10, array['breakfast']::text[], null),
  ('74b28d0b-4b64-98b4-d861-3ba9632b7c0e'::uuid, 'overnight-oats-peanut-banana', 'Βρώμη ολονυκτίας με φυστικοβούτυρο και μπανάνα', 'Overnight oats with peanut butter and banana', array['Ανακατέψτε σε βάζο τη βρώμη, τους σπόρους τσία, την κανέλα, το γάλα αμυγδάλου και το σιρόπι σφενδάμου.','Κλείστε και αφήστε στο ψυγείο όλη νύχτα.','Το πρωί προσθέστε το φυστικοβούτυρο και σερβίρετε με φέτες μπανάνας.']::text[], array['In a jar, combine the oats, chia seeds, cinnamon, almond milk and maple syrup.','Seal and leave in the fridge overnight.','In the morning stir in the peanut butter and top with banana slices.']::text[], 2, 10, array['breakfast']::text[], null),
  ('0a4c0821-7a66-1ae0-05e9-38ebf195e599'::uuid, 'polenta-mushroom-ragout', 'Κρεμώδης πολέντα με ραγού μανιταριών', 'Creamy polenta with mushroom ragout', array['Σοτάρετε το κρεμμύδι και το σκόρδο στο ελαιόλαδο, προσθέστε τα μανιτάρια κομμένα σε φέτες και μαγειρέψτε σε δυνατή φωτιά μέχρι να ροδίσουν.','Ρίξτε τις ντομάτες κονσέρβας, το θυμάρι, το μισό αλάτι και το πιπέρι και σιγοβράστε 15 λεπτά να δέσει η σάλτσα.','Βράστε το νερό με το υπόλοιπο αλάτι, ρίξτε το καλαμποκάλευρο σιγά σιγά ανακατεύοντας και μαγειρέψτε 25–30 λεπτά σε χαμηλή φωτιά.','Αποσύρετε, ανακατέψτε την παρμεζάνα και το βούτυρο μέσα στην πολέντα και σερβίρετε με το ραγού από πάνω.']::text[], array['Sauté the onion and garlic in the olive oil, add the sliced mushrooms and cook over high heat until browned.','Add the canned tomatoes, thyme, half the salt and the pepper and simmer 15 minutes until the sauce thickens.','Bring the water to the boil with the remaining salt, pour in the cornmeal slowly while stirring and cook 25–30 minutes over low heat.','Off the heat, stir the parmesan and butter into the polenta and serve with the ragout on top.']::text[], 4, 50, array['lunch','dinner']::text[], null),
  ('9a20bf5a-43c9-4212-41af-662d258707be'::uuid, 'pork-tenderloin-roasted-carrots-potatoes', 'Ψαρονέφρι με ψητά καρότα, πατάτες και δεντρολίβανο', 'Pork tenderloin with roasted carrots, potatoes and rosemary', array['Κόψτε τα καρότα και τις πατάτες σε κομμάτια, ανακατέψτε με 2 κουταλιές ελαιόλαδο, το δεντρολίβανο, το μισό αλάτι και πιπέρι και ψήστε στους 200°C για 20 λεπτά.','Αλείψτε το ψαρονέφρι με τη μουστάρδα, το υπόλοιπο αλάτι και πιπέρι και θωρακίστε το στο υπόλοιπο ελαιόλαδο 2 λεπτά από κάθε πλευρά.','Βάλτε το ψαρονέφρι πάνω στα λαχανικά και ψήστε 18–20 λεπτά· αφήστε το 5 λεπτά πριν το κόψετε.','Σερβίρετε με χυμό λεμονιού και το πράσινο μέρος του φρέσκου κρεμμυδιού ψιλοκομμένο.']::text[], array['Cut the carrots and potatoes into chunks, toss with 2 tablespoons of olive oil, the rosemary and half the salt and pepper and roast at 200°C for 20 minutes.','Rub the tenderloin with the mustard and the rest of the salt and pepper and sear it in the remaining olive oil 2 minutes per side.','Set the tenderloin on top of the vegetables and roast 18–20 minutes; rest 5 minutes before slicing.','Serve with a squeeze of lemon and the chopped green part of the spring onion.']::text[], 4, 55, array['lunch','dinner']::text[], null),
  ('35c312c3-ab12-9d48-5cba-2db530723b8a'::uuid, 'psari-plaki-baked-cod-tomato-onion', 'Ψάρι πλακί', 'Psari plaki — cod baked with tomato and onion', array['Σοτάρετε στο μισό ελαιόλαδο τα κρεμμύδια σε φέτες και το σκόρδο μέχρι να μαλακώσουν.','Προσθέστε τις ντομάτες και τον μαϊντανό και σιγοβράστε 10 λεπτά.','Στρώστε τις πατάτες σε λεπτές φέτες σε ταψί, ακουμπήστε από πάνω τα φιλέτα και σκεπάστε με τη σάλτσα.','Περιχύστε με το υπόλοιπο λάδι και ψήστε στους 190 °C για 40 λεπτά.']::text[], array['Sauté the sliced onions and garlic in half the olive oil until soft.','Add the tomatoes and parsley and simmer for 10 minutes.','Layer thinly sliced potatoes in a baking dish, lay the fillets on top and cover with the sauce.','Drizzle with the remaining oil and bake at 190 °C for 40 minutes.']::text[], 4, 65, array['lunch','dinner']::text[], null),
  ('132d220f-702e-8ac2-0758-b676a21a8f63'::uuid, 'pumpkin-red-lentil-soup', 'Σούπα κολοκύθας με κόκκινες φακές', 'Pumpkin and red lentil soup', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι, το καρότο, το σκόρδο και το τζίντζερ ψιλοκομμένα για 5 λεπτά.','Προσθέστε την κολοκύθα σε κύβους, τις φακές, το κύμινο και το νερό.','Σιγοβράστε 25 λεπτά μέχρι να μαλακώσουν όλα.','Πολτοποιήστε με ραβδομπλέντερ και σερβίρετε.']::text[], array['Sauté the chopped onion, carrot, garlic and ginger in the olive oil for 5 minutes.','Add the cubed pumpkin, the lentils, the cumin and the water.','Simmer for 25 minutes until everything is soft.','Blend with a stick blender and serve.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('2c477586-a550-fd75-4925-1978b461ef65'::uuid, 'pumpkin-sage-risotto', 'Ριζότο κολοκύθας με φασκόμηλο', 'Pumpkin and sage risotto', array['Κόψτε την κολοκύθα σε μικρούς κύβους και σοτάρετέ τη με το κρεμμύδι στο ελαιόλαδο για 8 λεπτά.','Προσθέστε το ρύζι, ανακατέψτε 1 λεπτό να γυαλίσει και σβήστε με το κρασί.','Ρίχνετε το ζεστό αλατισμένο νερό μία κουτάλα τη φορά, ανακατεύοντας, μέχρι να απορροφηθεί — περίπου 18 λεπτά.','Αποσύρετε και ανακατέψτε το βούτυρο, την παρμεζάνα, το φασκόμηλο και το πιπέρι· αφήστε 2 λεπτά σκεπασμένο πριν σερβίρετε.']::text[], array['Cut the pumpkin into small cubes and sauté it with the onion in the olive oil for 8 minutes.','Add the rice, stir 1 minute until glossy and deglaze with the wine.','Add the hot salted water a ladle at a time, stirring, until absorbed — about 18 minutes.','Off the heat, stir in the butter, parmesan, sage and pepper; rest covered 2 minutes before serving.']::text[], 4, 45, array['lunch','dinner']::text[], null),
  ('9f7e9b3a-0961-6857-6750-6f76aebf578c'::uuid, 'quinoa-black-bean-sweet-potato-bowl', 'Μπολ κινόα με μαύρα φασόλια, ψητή γλυκοπατάτα και αβοκάντο', 'Quinoa, black bean and roasted sweet potato bowl with avocado', array['Μουλιάστε τα μαύρα φασόλια από το προηγούμενο βράδυ και βράστε τα 60–75 λεπτά μέχρι να μαλακώσουν· στραγγίστε.','Κόψτε τη γλυκοπατάτα σε κύβους, ανακατέψτε με 1 κουταλιά ελαιόλαδο, το κύμινο, την πάπρικα και το αλάτι και ψήστε στους 200°C για 25 λεπτά.','Ξεπλύνετε και βράστε την κινόα 15 λεπτά σε διπλάσιο νερό.','Μοιράστε την κινόα σε μπολ με τα φασόλια, τη γλυκοπατάτα, τα ντοματίνια, το κρεμμύδι και το αβοκάντο· περιχύστε με το υπόλοιπο ελαιόλαδο και τον χυμό του λάιμ και πασπαλίστε με κόλιανδρο.']::text[], array['Soak the black beans overnight and boil 60–75 minutes until tender; drain.','Dice the sweet potato, toss with 1 tablespoon of olive oil, the cumin, paprika and salt and roast at 200°C for 25 minutes.','Rinse and cook the quinoa 15 minutes in twice its volume of water.','Divide the quinoa between bowls with the beans, sweet potato, cherry tomatoes, onion and avocado; drizzle with the remaining olive oil and lime juice and scatter with coriander.']::text[], 4, 90, array['lunch','dinner']::text[], null),
  ('70d18c2f-a22a-7cd4-40ae-d02a5dec7c3f'::uuid, 'quinoa-porridge-orange-walnuts', 'Χυλός κινόα με πορτοκάλι, κανέλα και καρύδια', 'Quinoa porridge with orange, cinnamon and walnuts', array['Ξεπλύνετε καλά την κινόα και βάλτε τη σε κατσαρόλα με το γάλα αμυγδάλου, την κανέλα και τη βανίλια.','Σιγοβράστε 15–18 λεπτά ανακατεύοντας πού και πού, μέχρι να απορροφηθεί το υγρό και να ανοίξουν οι σπόροι.','Γλυκάνετε με το σιρόπι σφενδάμου και σερβίρετε με φέτες πορτοκαλιού και χοντροκομμένα καρύδια.']::text[], array['Rinse the quinoa well and put it in a saucepan with the almond milk, cinnamon and vanilla.','Simmer 15–18 minutes, stirring now and then, until the liquid is absorbed and the grains have opened.','Sweeten with the maple syrup and serve with orange segments and roughly chopped walnuts.']::text[], 2, 25, array['breakfast']::text[], null),
  ('3ee22f3a-0e42-0222-8f17-8e9094b14afe'::uuid, 'quinoa-roasted-vegetable-feta-bowl', 'Μπολ κινόα με ψητά λαχανικά, φέτα και κολοκυθόσπορους', 'Quinoa bowl with roasted vegetables, feta and pumpkin seeds', array['Κόψτε τα καρότα, το κολοκυθάκι και την πιπεριά σε κομμάτια, ανακατέψτε με 2 κουταλιές ελαιόλαδο, τη ρίγανη, το αλάτι και το πιπέρι και ψήστε στους 200°C για 25 λεπτά.','Στο μεταξύ ξεπλύνετε και βράστε την κινόα 15 λεπτά σε διπλάσιο νερό.','Μοιράστε την κινόα σε μπολ, προσθέστε τα ψητά λαχανικά, θρυμματίστε τη φέτα από πάνω και πασπαλίστε με κολοκυθόσπορους και το πράσινο μέρος του φρέσκου κρεμμυδιού.','Περιχύστε με το υπόλοιπο ελαιόλαδο και τον χυμό λεμονιού.']::text[], array['Cut the carrots, zucchini and pepper into chunks, toss with 2 tablespoons of olive oil, the oregano, salt and pepper and roast at 200°C for 25 minutes.','Meanwhile rinse and cook the quinoa 15 minutes in twice its volume of water.','Divide the quinoa between bowls, add the roasted vegetables, crumble the feta on top and sprinkle with pumpkin seeds and the green part of the spring onion.','Drizzle with the remaining olive oil and the lemon juice.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('70d077f1-ad6e-c9c7-9756-515ba268014c'::uuid, 'quinoa-tabbouleh', 'Ταμπουλέ με κινόα', 'Quinoa tabbouleh', array['Ξεπλύντε την κινόα και βράστε τη 15 λεπτά σε διπλάσιο νερό· στραγγίστε και αφήστε να κρυώσει.','Ψιλοκόψτε τον μαϊντανό, τον δυόσμο, τις ντομάτες, το αγγούρι και τα φρέσκα κρεμμυδάκια.','Ανακατέψτε τα όλα με την κινόα.','Περιχύστε με τον χυμό του λεμονιού και το ελαιόλαδο.']::text[], array['Rinse the quinoa and boil for 15 minutes in twice its volume of water; drain and cool.','Finely chop the parsley, mint, tomatoes, cucumber and spring onions.','Toss everything with the quinoa.','Dress with the lemon juice and olive oil.']::text[], 2, 30, array['lunch','dinner']::text[], null),
  ('36a46aa1-534d-2f26-9497-0e03b547c0ba'::uuid, 'revithada-sifnos-baked-chickpeas', 'Ρεβιθάδα Σίφνου', 'Revithada — Sifnos slow-baked chickpeas', array['Μουλιάστε τα ρεβίθια 12 ώρες και στραγγίστε.','Βάλτε τα σε πήλινο ή γάστρα με το κρεμμύδι ψιλοκομμένο, το ελαιόλαδο, τη δάφνη και το δεντρολίβανο.','Προσθέστε νερό να τα σκεπάζει κατά 2 δάχτυλα και σκεπάστε.','Ψήστε στους 160 °C για 3 ώρες μέχρι να μαλακώσουν και να δέσει το ζουμί.','Σερβίρετε με πιπέρι και λεμόνι.']::text[], array['Soak the chickpeas for 12 hours and drain.','Put them in a clay pot or casserole with the chopped onion, olive oil, bay leaves and rosemary.','Add water to cover by about 3 cm and put the lid on.','Bake at 160 °C for 3 hours until the chickpeas are soft and the liquid has thickened.','Serve with pepper and lemon.']::text[], 4, 200, array['lunch','dinner']::text[], null),
  ('3a69e9ff-dbbe-bf5a-40e8-6ab5dc5ef23f'::uuid, 'rice-cakes-peanut-butter-banana', 'Ρυζογκοφρέτες με φυστικοβούτυρο και μπανάνα', 'Rice cakes with peanut butter and banana', array['Αλείψτε τις ρυζογκοφρέτες με το φυστικοβούτυρο.','Κόψτε την μπανάνα σε ροδέλες και απλώστε τες από πάνω.','Σερβίρετε αμέσως για να μείνουν τραγανές.']::text[], array['Spread the rice cakes with the peanut butter.','Slice the banana into rounds and arrange on top.','Serve immediately so they stay crisp.']::text[], 1, 5, array['snack']::text[], null),
  ('52871f56-f89e-c887-b292-04b0e2d3b927'::uuid, 'rice-cakes-smoked-salmon-egg', 'Ρυζογκοφρέτες με καπνιστό σολομό, αυγό και ρόκα', 'Rice cakes with smoked salmon, egg and rocket', array['Βράστε τα αυγά 8 λεπτά, κρυώστε τα σε κρύο νερό και κόψτε τα σε φέτες.','Ανακατέψτε τη ρόκα με το ελαιόλαδο, τον χυμό λεμονιού και το πιπέρι.','Μοιράστε τη ρόκα στις ρυζογκοφρέτες, στρώστε τον σολομό και το αυγό και τελειώστε με ψιλοκομμένο άνηθο.']::text[], array['Boil the eggs for 8 minutes, cool them in cold water and slice.','Toss the rocket with the olive oil, lemon juice and pepper.','Divide the rocket over the rice cakes, layer on the salmon and egg and finish with chopped dill.']::text[], 2, 15, array['breakfast','snack']::text[], null),
  ('252d11cf-ad3e-3458-41ca-f5eb2d40f0af'::uuid, 'rice-noodle-tofu-peanut-salad', 'Σαλάτα με ρυζομακάρονα, τόφου, αγγούρι και φιστίκια', 'Rice noodle salad with tofu, cucumber and peanuts', array['Κόψτε το τόφου σε κύβους, στεγνώστε το καλά και ψήστε το στο ελαιόλαδο μέχρι να ροδίσει από όλες τις πλευρές.','Βράστε τα ρυζομακάρονα σύμφωνα με τις οδηγίες, ξεπλύνετε με κρύο νερό και στραγγίστε.','Χτυπήστε τον χυμό του λάιμ με το σησαμέλαιο, το σιρόπι σφενδάμου, το τριμμένο τζίντζερ και το αλάτι.','Ανακατέψτε τα ρυζομακάρονα με το αγγούρι και το καρότο σε λεπτές λωρίδες, το πράσινο μέρος του φρέσκου κρεμμυδιού και τη σάλτσα· προσθέστε το τόφου, τα φιστίκια και τον κόλιανδρο.']::text[], array['Cube the tofu, pat it very dry and fry in the olive oil until golden on all sides.','Cook the rice noodles according to the packet, rinse under cold water and drain.','Whisk the lime juice with the sesame oil, maple syrup, grated ginger and salt.','Toss the noodles with the cucumber and carrot cut into thin strips, the green part of the spring onion and the dressing; add the tofu, peanuts and coriander.']::text[], 4, 35, array['lunch','dinner']::text[], null),
  ('b6b30f56-113f-2529-73d5-1d6ed9b67f73'::uuid, 'roasted-cauliflower-tahini-pomegranate', 'Ψητό κουνουπίδι με ταχίνι και ρόδι', 'Roasted cauliflower with tahini and pomegranate', array['Κόψτε το κουνουπίδι σε μπουκέτα, ανακατέψτε με το ελαιόλαδο και το κύμινο και απλώστε σε ταψί.','Ψήστε στους 220 °C για 25 λεπτά μέχρι να ροδίσει στις άκρες.','Ανακατέψτε το ταχίνι με τον χυμό του λεμονιού, το σκόρδο λιωμένο και 3 κουταλιές νερό μέχρι να γίνει σάλτσα.','Περιχύστε το κουνουπίδι με τη σάλτσα και σκορπίστε από πάνω το ρόδι και τον μαϊντανό.']::text[], array['Cut the cauliflower into florets, toss with the olive oil and cumin and spread on a tray.','Roast at 220 °C for 25 minutes until browned at the edges.','Whisk the tahini with the lemon juice, crushed garlic and 3 tablespoons of water into a sauce.','Spoon the sauce over the cauliflower and scatter with pomegranate seeds and parsley.']::text[], 2, 35, array['lunch','dinner']::text[], null),
  ('9b68b9ff-b7ae-8b2c-6f57-3ca932e244a4'::uuid, 'roasted-chickpeas-paprika-cumin', 'Ψητά ρεβίθια με πάπρικα και κύμινο', 'Roasted chickpeas with paprika and cumin', array['Μουλιάστε τα ρεβίθια 12 ώρες, βράστε τα 45 λεπτά να μείνουν σφιχτά και στεγνώστε τα καλά σε πετσέτα.','Ανακατέψτε τα με το ελαιόλαδο, την πάπρικα και το κύμινο.','Απλώστε σε ταψί και ψήστε στους 200 °C για 30 λεπτά ανακινώντας στα μισά, μέχρι να γίνουν τραγανά.']::text[], array['Soak the chickpeas for 12 hours, boil for 45 minutes so they stay firm and dry them well on a towel.','Toss with the olive oil, paprika and cumin.','Spread on a tray and roast at 200 °C for 30 minutes, shaking halfway, until crunchy.']::text[], 4, 80, array['snack']::text[], null),
  ('3340f898-6b18-d837-efc3-b381fa1d78a6'::uuid, 'salmon-quinoa-broccoli-bowl', 'Μπολ με σολομό, κινόα και μπρόκολο', 'Salmon, quinoa and broccoli bowl', array['Βράστε την κινόα 15 λεπτά σε διπλάσιο νερό και στραγγίστε.','Αχνίστε το μπρόκολο 5 λεπτά.','Ψήστε τον σολομό σε αντικολλητικό τηγάνι με το ελαιόλαδο 4 λεπτά από κάθε πλευρά.','Μοιράστε την κινόα σε μπολ, βάλτε από πάνω το μπρόκολο, τον σολομό και το αβοκάντο σε φέτες και περιχύστε με λεμόνι και άνηθο.']::text[], array['Boil the quinoa for 15 minutes in twice its volume of water and drain.','Steam the broccoli for 5 minutes.','Pan-fry the salmon in the olive oil for 4 minutes per side.','Divide the quinoa between bowls, top with the broccoli, salmon and sliced avocado and finish with lemon and dill.']::text[], 2, 30, array['lunch','dinner']::text[], null),
  ('43472688-4985-9932-034c-8ac53dcf6aa2'::uuid, 'seasonal-fruit-salad-walnuts', 'Φρουτοσαλάτα με καρύδια και κανέλα', 'Seasonal fruit salad with walnuts and cinnamon', array['Καθαρίστε τα πορτοκάλια και κόψτε τα σε κύβους μαζί με το μήλο και την μπανάνα.','Βγάλτε τους σπόρους από το μισό ρόδι.','Ανακατέψτε όλα τα φρούτα σε μπολ με τα καρύδια και πασπαλίστε με κανέλα.']::text[], array['Peel the oranges and dice them together with the apple and banana.','Remove the seeds from half a pomegranate.','Toss all the fruit in a bowl with the walnuts and dust with cinnamon.']::text[], 2, 10, array['breakfast','snack']::text[], null),
  ('343658e3-f5f8-3fc6-3423-c727833428ca'::uuid, 'sheet-pan-chicken-sweet-potato-broccoli', 'Κοτόπουλο ταψιού με γλυκοπατάτα, μπρόκολο και λεμόνι', 'Sheet-pan chicken with sweet potato, broccoli and lemon', array['Προθερμάνετε τον φούρνο στους 210°C. Ανακατέψτε τα μπούτια με 2 κουταλιές ελαιόλαδο, την πάπρικα, τη ρίγανη, το λιωμένο σκόρδο, το αλάτι και το πιπέρι.','Κόψτε τη γλυκοπατάτα σε κύβους και το κρεμμύδι σε φέτες, ανακατέψτε με το υπόλοιπο ελαιόλαδο και απλώστε τα σε ταψί μαζί με το κοτόπουλο· ψήστε 25 λεπτά.','Προσθέστε το μπρόκολο σε μπουκετάκια και τις φέτες λεμονιού, ανακατέψτε και ψήστε 15–20 λεπτά ακόμη μέχρι το κοτόπουλο να ροδίσει και η γλυκοπατάτα να μαλακώσει.']::text[], array['Preheat the oven to 210°C. Toss the thighs with 2 tablespoons of olive oil, the paprika, oregano, crushed garlic, salt and pepper.','Dice the sweet potato and slice the onion, toss with the remaining olive oil and spread on a tray with the chicken; roast 25 minutes.','Add the broccoli florets and lemon slices, toss and roast 15–20 minutes more until the chicken is golden and the sweet potato tender.']::text[], 4, 55, array['lunch','dinner']::text[], null),
  ('5cc5ae63-86d4-e03b-5f8f-f9e4a0a2f652'::uuid, 'sheet-pan-salmon-asparagus-potatoes', 'Σολομός ταψιού με σπαράγγια, πατάτες και άνηθο', 'Sheet-pan salmon with asparagus, potatoes and dill', array['Κόψτε τις πατάτες σε κομμάτια, ανακατέψτε με 2 κουταλιές ελαιόλαδο, το μισό αλάτι και πιπέρι και ψήστε στους 210°C για 25 λεπτά.','Προσθέστε στο ταψί τον σολομό και τα σπαράγγια, περιχύστε με το υπόλοιπο ελαιόλαδο, το λιωμένο σκόρδο, το υπόλοιπο αλάτι και πιπέρι και φέτες λεμονιού.','Ψήστε 12–14 λεπτά ακόμη, μέχρι ο σολομός να ξεφλουδίζει με το πιρούνι, και πασπαλίστε με ψιλοκομμένο άνηθο.']::text[], array['Cut the potatoes into chunks, toss with 2 tablespoons of olive oil and half the salt and pepper and roast at 210°C for 25 minutes.','Add the salmon and asparagus to the tray, drizzle with the remaining olive oil, crushed garlic, the rest of the salt and pepper and lemon slices.','Roast 12–14 minutes more, until the salmon flakes with a fork, and scatter with chopped dill.']::text[], 4, 50, array['lunch','dinner']::text[], null),
  ('dd1de48e-9cbe-6734-9046-a6496906f3c6'::uuid, 'shrimp-lemon-risotto', 'Ριζότο με γαρίδες, λεμόνι και μαϊντανό', 'Shrimp risotto with lemon and parsley', array['Σοτάρετε το κρεμμύδι και το σκόρδο σε 2 κουταλιές ελαιόλαδο μέχρι να μαλακώσουν, προσθέστε το ρύζι και ανακατέψτε 1 λεπτό.','Σβήστε με το κρασί και ρίχνετε το ζεστό αλατισμένο νερό μία κουτάλα τη φορά, ανακατεύοντας, για περίπου 16 λεπτά.','Σοτάρετε τις γαρίδες στο υπόλοιπο ελαιόλαδο 2 λεπτά από κάθε πλευρά με το πιπέρι.','Ανακατέψτε στο ριζότο το βούτυρο, τον χυμό και το ξύσμα του λεμονιού και τον μαϊντανό· σερβίρετε με τις γαρίδες από πάνω.']::text[], array['Sauté the onion and garlic in 2 tablespoons of olive oil until soft, add the rice and stir 1 minute.','Deglaze with the wine and add the hot salted water a ladle at a time, stirring, for about 16 minutes.','Sear the shrimp in the remaining olive oil 2 minutes per side with the pepper.','Stir the butter, lemon juice and zest and parsley into the risotto; serve with the shrimp on top.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('4c1a2ef6-6e07-b256-f6cb-85b858271a3e'::uuid, 'shrimp-saganaki-feta-ouzo', 'Γαρίδες σαγανάκι', 'Shrimp saganaki with feta and ouzo', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι και το σκόρδο ψιλοκομμένα για 5 λεπτά.','Προσθέστε τις ντομάτες και τις νιφάδες τσίλι και σιγοβράστε 15 λεπτά.','Ρίξτε τις γαρίδες και το ούζο και μαγειρέψτε 4 λεπτά μέχρι να ροδίσουν.','Θρυμματίστε τη φέτα από πάνω, σκεπάστε 2 λεπτά να μαλακώσει και σερβίρετε με μαϊντανό.']::text[], array['Sauté the chopped onion and garlic in the olive oil for 5 minutes.','Add the tomatoes and chilli flakes and simmer for 15 minutes.','Add the shrimp and ouzo and cook for 4 minutes until pink.','Crumble the feta over, cover for 2 minutes to soften and serve with parsley.']::text[], 2, 35, array['dinner']::text[], null),
  ('5cc6498c-b667-809a-de24-ad8dee726a9a'::uuid, 'skyr-berry-oat-bowl', 'Σκυρ με μούρα, βρώμη και τσία', 'Skyr bowl with berries, oats and chia', array['Βάλτε το σκυρ σε μπολ και ανακατέψτε μέσα τους σπόρους τσία.','Πλύντε τις φράουλες και κόψτε τες στη μέση.','Σκορπίστε από πάνω τη βρώμη, τις φράουλες και τα μύρτιλα.']::text[], array['Spoon the skyr into a bowl and stir in the chia seeds.','Rinse the strawberries and halve them.','Scatter the oats, strawberries and blueberries over the top.']::text[], 1, 5, array['breakfast','snack']::text[], null),
  ('5b3e8a4d-33a3-c3b2-0874-8b4f08d42d76'::uuid, 'skyr-bowl-kiwi-strawberry', 'Μπολ σκυρ με ακτινίδιο, φράουλες και κολοκυθόσπορους', 'Skyr bowl with kiwi, strawberries and pumpkin seeds', array['Μοιράστε το σκυρ σε δύο μπολ.','Κόψτε το ακτινίδιο και τις φράουλες και απλώστε τα από πάνω.','Πασπαλίστε με κολοκυθόσπορους και σπόρους τσία και περιχύστε με το μέλι.']::text[], array['Divide the skyr between two bowls.','Slice the kiwi and strawberries and arrange them on top.','Sprinkle with pumpkin seeds and chia seeds and drizzle with the honey.']::text[], 2, 5, array['breakfast','snack']::text[], null),
  ('37cfa1ed-3f8d-41a4-4ae8-ecefbe611c30'::uuid, 'smoked-salmon-skyr-toast', 'Τοστ με σκυρ, καπνιστό σολομό και αγγούρι', 'Smoked salmon toast with skyr and cucumber', array['Φρυγανίστε το ψωμί και απλώστε το σκυρ σε κάθε φέτα.','Κόψτε το αγγούρι σε λεπτές ροδέλες και στρώστε τες πάνω στο σκυρ.','Ακουμπήστε από πάνω τον σολομό, ψιλοκομμένο άνηθο και λίγες σταγόνες λεμόνι.']::text[], array['Toast the bread and spread the skyr over each slice.','Slice the cucumber thinly and lay it over the skyr.','Top with the salmon, chopped dill and a squeeze of lemon.']::text[], 1, 10, array['breakfast','lunch']::text[], null),
  ('4bf87b2a-e251-82f8-0d29-1de4e3ae3d9a'::uuid, 'socca-roasted-peppers-rocket', 'Σόκα (τηγανίτα ρεβιθάλευρου) με ψητές πιπεριές και ρόκα', 'Socca (chickpea flour flatbread) with roasted peppers and rocket', array['Χτυπήστε το ρεβιθάλευρο με το νερό, 1 κουταλιά ελαιόλαδο, το δεντρολίβανο και το αλάτι και αφήστε τον χυλό 30 λεπτά.','Ζεστάνετε 1 κουταλιά ελαιόλαδο σε τηγάνι που μπαίνει στον φούρνο, ρίξτε τον χυλό και ψήστε στους 230°C για 12–15 λεπτά μέχρι να ροδίσουν οι άκρες.','Κόψτε σε κομμάτια και σερβίρετε με τις ψητές πιπεριές, τη ρόκα, τις ελιές, το υπόλοιπο ελαιόλαδο και τον χυμό λεμονιού.']::text[], array['Whisk the chickpea flour with the water, 1 tablespoon of olive oil, the rosemary and salt and rest the batter 30 minutes.','Heat 1 tablespoon of olive oil in an ovenproof pan, pour in the batter and bake at 230°C for 12–15 minutes until the edges are golden.','Cut into wedges and serve with the roasted peppers, rocket, olives, the remaining olive oil and the lemon juice.']::text[], 3, 55, array['lunch','dinner']::text[], null),
  ('f1aa503b-f304-154e-c015-5a617fbc1538'::uuid, 'spaghetti-tomato-garlic-basil', 'Μακαρόνια ολικής με σάλτσα ντομάτας και βασιλικό', 'Whole wheat spaghetti with tomato, garlic and basil', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι και το σκόρδο ψιλοκομμένα για 3 λεπτά.','Ρίξτε τις ντομάτες και σιγοβράστε 20 λεπτά μέχρι να δέσει η σάλτσα.','Βράστε τα μακαρόνια σύμφωνα με τη συσκευασία και στραγγίστε.','Ανακατέψτε τα με τη σάλτσα, τον βασιλικό και το πιπέρι και σερβίρετε.']::text[], array['Sauté the chopped onion and garlic in the olive oil for 3 minutes.','Add the tomatoes and simmer for 20 minutes until the sauce thickens.','Cook the spaghetti according to the packet and drain.','Toss with the sauce, the basil and the pepper and serve.']::text[], 2, 30, array['lunch','dinner']::text[], null),
  ('73def358-808b-e838-4f3e-8ebcad924b77'::uuid, 'spanakopita-spinach-feta-pie', 'Σπανακόπιτα', 'Spanakopita — spinach and feta pie', array['Μαράντε το σπανάκι σε μεγάλο τηγάνι, στραγγίστε το πολύ καλά και ψιλοκόψτε το.','Ανακατέψτε το με τα φρέσκα κρεμμυδάκια και τον άνηθο ψιλοκομμένους, τη φέτα θρυμματισμένη και τα αυγά.','Λαδώστε ταψί και στρώστε τα μισά φύλλα, λαδώνοντας το καθένα.','Απλώστε τη γέμιση και σκεπάστε με τα υπόλοιπα φύλλα, λαδώνοντας· χαράξτε σε κομμάτια.','Ψήστε στους 180 °C για 45 λεπτά μέχρι να ροδίσει.']::text[], array['Wilt the spinach in a large pan, squeeze it very dry and chop it.','Mix it with the chopped spring onions and dill, the crumbled feta and the eggs.','Oil a baking tin and lay in half the phyllo sheets, brushing each with oil.','Spread the filling, cover with the remaining sheets, brushing with oil; score into pieces.','Bake at 180 °C for 45 minutes until golden.']::text[], 6, 80, array['lunch','dinner','snack']::text[], null),
  ('a6f2e5b9-6bc0-4889-c84f-1cbb06e8f047'::uuid, 'spanakorizo-spinach-rice', 'Σπανακόρυζο', 'Spanakorizo — spinach rice with dill and lemon', array['Σοτάρετε στο ελαιόλαδο το κρεμμύδι και τα φρέσκα κρεμμυδάκια ψιλοκομμένα για 5 λεπτά.','Ρίξτε το σπανάκι σε δόσεις και ανακατεύετε μέχρι να μαραθεί.','Προσθέστε το ρύζι, τον άνηθο και 400 ml νερό και σιγοβράστε 20 λεπτά σκεπασμένο.','Αποσύρετε, στύψτε το λεμόνι και αφήστε το 5 λεπτά πριν σερβίρετε.']::text[], array['Sauté the chopped onion and spring onions in the olive oil for 5 minutes.','Add the spinach in batches and stir until wilted.','Add the rice, dill and 400 ml water and simmer, covered, for 20 minutes.','Take off the heat, squeeze in the lemon and rest for 5 minutes before serving.']::text[], 4, 40, array['lunch','dinner']::text[], null),
  ('95599eb8-4318-8369-6d4e-0690c617827a'::uuid, 'strapatsada-tomato-scrambled-eggs', 'Στραπατσάδα (καγιανάς)', 'Strapatsada — Greek tomato scrambled eggs', array['Τρίψτε τις ντομάτες στον τρίφτη και πετάξτε τη φλούδα.','Ζεστάνετε το ελαιόλαδο σε αντικολλητικό τηγάνι και ρίξτε την τριμμένη ντομάτα με τη ρίγανη.','Μαγειρέψτε 8–10 λεπτά σε μέτρια φωτιά μέχρι να φύγουν τα υγρά.','Χτυπήστε ελαφρά τα αυγά, ρίξτε τα στο τηγάνι και ανακατεύετε μέχρι να δέσουν.','Θρυμματίστε από πάνω τη φέτα και σερβίρετε με το ψωμί.']::text[], array['Grate the tomatoes on a box grater and discard the skins.','Heat the olive oil in a non-stick pan and add the grated tomato with the oregano.','Cook for 8–10 minutes over medium heat until the liquid has evaporated.','Lightly beat the eggs, pour them in and stir until just set.','Crumble the feta over the top and serve with the bread.']::text[], 2, 20, array['breakfast','lunch']::text[], null),
  ('98ba68ef-0dfe-b630-9703-095d016c29e7'::uuid, 'sweet-potato-hash-eggs', 'Γλυκοπατάτα τηγανιού με αυγά και σπανάκι', 'Sweet potato hash with eggs and spinach', array['Κόψτε τη γλυκοπατάτα και την πιπεριά σε μικρούς κύβους.','Σοτάρετε τη γλυκοπατάτα στο ελαιόλαδο σε μέτρια φωτιά για 10 λεπτά, προσθέστε την πιπεριά, την πάπρικα, το αλάτι και το πιπέρι και μαγειρέψτε 5 λεπτά ακόμη.','Προσθέστε το σπανάκι και το πράσινο μέρος του φρέσκου κρεμμυδιού και ανακατέψτε μέχρι να μαραθεί.','Ανοίξτε τέσσερις λακκούβες, σπάστε μέσα τα αυγά, σκεπάστε και μαγειρέψτε 4–5 λεπτά μέχρι να πήξουν τα ασπράδια.']::text[], array['Dice the sweet potato and the pepper into small cubes.','Sauté the sweet potato in the olive oil over medium heat for 10 minutes, add the pepper, paprika, salt and pepper and cook 5 minutes more.','Add the spinach and the green part of the spring onion and stir until wilted.','Make four wells, crack in the eggs, cover and cook 4–5 minutes until the whites are set.']::text[], 2, 30, array['breakfast','lunch']::text[], null),
  ('fccd083f-dec3-90dd-acc1-30a433a79496'::uuid, 'tahini-petimezi-toast', 'Ψωμί με ταχίνι και πετιμέζι', 'Tahini and petimezi toast', array['Φρυγανίστε τις φέτες ψωμιού.','Απλώστε το ταχίνι σε κάθε φέτα.','Περιχύστε με το πετιμέζι και πασπαλίστε με το σουσάμι.']::text[], array['Toast the bread.','Spread the tahini over each slice.','Drizzle with the petimezi and sprinkle with the sesame seeds.']::text[], 1, 5, array['breakfast','snack']::text[], null),
  ('bda1e865-5695-3783-cafe-cf53d4dfc02c'::uuid, 'tofu-scramble-turmeric-peppers', 'Σκράμπλ τόφου με κουρκουμά και πιπεριά', 'Turmeric tofu scramble with peppers', array['Στραγγίστε το τόφου και θρυμματίστε το με πιρούνι.','Σοτάρετε στο ελαιόλαδο το κρεμμύδι και την πιπεριά ψιλοκομμένα για 5 λεπτά.','Ρίξτε το τόφου, τον κουρκουμά και το πιπέρι και ανακατεύετε 5 λεπτά.','Προσθέστε το σπανάκι και τη διατροφική μαγιά, ανακατέψτε μέχρι να μαραθεί και σερβίρετε.']::text[], array['Drain the tofu and crumble it with a fork.','Sauté the chopped onion and pepper in the olive oil for 5 minutes.','Add the tofu, turmeric and black pepper and stir for 5 minutes.','Add the spinach and nutritional yeast, stir until wilted and serve.']::text[], 2, 15, array['breakfast','lunch']::text[], null),
  ('52073cf0-1d90-4f74-4fd4-27450bea64f2'::uuid, 'tofu-souvlaki-skewers-pita', 'Σουβλάκι τόφου με πίτα', 'Tofu souvlaki skewers with pita', array['Κόψτε το τόφου σε κύβους και μαρινάρετέ το 20 λεπτά με το ελαιόλαδο, τον χυμό του λεμονιού, τη ρίγανη και την πάπρικα.','Κόψτε την πιπεριά, το κρεμμύδι και το κολοκύθι σε κομμάτια και περάστε τα σε σουβλάκια εναλλάξ με το τόφου.','Ψήστε σε γκριλ ή τηγάνι-σχάρα 10–12 λεπτά γυρίζοντας.','Ζεστάνετε τις πίτες και σερβίρετε με τα σουβλάκια.']::text[], array['Cube the tofu and marinate for 20 minutes in the olive oil, lemon juice, oregano and paprika.','Cut the pepper, onion and courgette into chunks and thread onto skewers alternating with the tofu.','Grill or griddle for 10–12 minutes, turning.','Warm the pitas and serve with the skewers.']::text[], 2, 40, array['lunch','dinner']::text[], null),
  ('e7021057-1ab5-6839-3cc1-ce6046b98350'::uuid, 'trahana-soup-feta', 'Τραχανάς σούπα με φέτα', 'Trahana soup with feta', array['Βράστε το νερό με το ελαιόλαδο και τον πελτέ.','Ρίξτε τον τραχανά και ανακατεύετε συχνά για 10–12 λεπτά μέχρι να χυλώσει.','Σερβίρετε ζεστό με θρυμματισμένη φέτα από πάνω.']::text[], array['Bring the water to the boil with the olive oil and tomato paste.','Add the trahana and stir often for 10–12 minutes until it thickens.','Serve hot with crumbled feta on top.']::text[], 2, 15, array['breakfast','dinner']::text[], null),
  ('a932f3cd-e6db-802d-8a40-2f1d9133ddc1'::uuid, 'tuna-potato-green-bean-salad', 'Σαλάτα με τόνο, πατάτες, φασολάκια και αυγό', 'Tuna, potato and green bean salad with egg', array['Βράστε τις πατάτες με τη φλούδα 20 λεπτά· τα τελευταία 6 λεπτά προσθέστε τα φασολάκια και, σε ξεχωριστή κατσαρόλα, βράστε τα αυγά 8 λεπτά.','Κόψτε τις πατάτες σε κομμάτια, τα ντοματίνια στη μέση, το κρεμμύδι σε λεπτές φέτες και τα αυγά στα τέσσερα.','Χτυπήστε το ελαιόλαδο με το ξίδι, τη μουστάρδα και το πιπέρι.','Ανακατέψτε πατάτες, φασολάκια, ντοματίνια, κρεμμύδι, ελιές και στραγγισμένο τόνο με τη σάλτσα· βάλτε τα αυγά από πάνω και πασπαλίστε με μαϊντανό.']::text[], array['Boil the potatoes in their skins for 20 minutes; add the green beans for the last 6 minutes and, in a separate pan, boil the eggs for 8 minutes.','Cut the potatoes into chunks, halve the cherry tomatoes, thinly slice the onion and quarter the eggs.','Whisk the olive oil with the vinegar, mustard and pepper.','Toss the potatoes, beans, tomatoes, onion, olives and drained tuna with the dressing; top with the eggs and sprinkle with parsley.']::text[], 4, 35, array['lunch','dinner']::text[], null),
  ('f8825764-e3a4-675e-5a22-f6d279312c05'::uuid, 'tuna-white-bean-salad', 'Σαλάτα με τόνο και φασόλια', 'Tuna and white bean salad', array['Μουλιάστε τα φασόλια από το προηγούμενο βράδυ, βράστε τα 60 λεπτά μέχρι να μαλακώσουν και στραγγίστε.','Στραγγίστε τον τόνο και ανακατέψτε τον με τα φασόλια, τα ντοματίνια κομμένα στη μέση και το κρεμμύδι σε λεπτές φέτες.','Περιχύστε με τον χυμό του λεμονιού και το ελαιόλαδο και σκορπίστε τον μαϊντανό.']::text[], array['Soak the beans overnight, boil for 60 minutes until tender and drain.','Drain the tuna and toss it with the beans, halved cherry tomatoes and thinly sliced onion.','Dress with the lemon juice and olive oil and scatter with parsley.']::text[], 2, 75, array['lunch']::text[], null),
  ('848aa6e7-6502-0530-11c4-6e8644f6c731'::uuid, 'turkey-spinach-breakfast-patties', 'Μπιφτεκάκια γαλοπούλας με σπανάκι και φασκόμηλο', 'Turkey and spinach breakfast patties', array['Ψιλοκόψτε το σπανάκι και το πράσινο μέρος του φρέσκου κρεμμυδιού και ζυμώστε τα με τον κιμά, το αυγό, το φασκόμηλο, το αλάτι και το πιπέρι.','Πλάστε οκτώ μικρά, επίπεδα μπιφτεκάκια.','Ψήστε τα στο ελαιόλαδο σε μέτρια φωτιά 4–5 λεπτά από κάθε πλευρά, μέχρι να ψηθούν καλά στο κέντρο.','Σερβίρετε με φέτες ντομάτας.']::text[], array['Finely chop the spinach and the green part of the spring onion and knead them into the mince with the egg, sage, salt and pepper.','Shape eight small, flat patties.','Cook them in the olive oil over medium heat 4–5 minutes per side, until cooked through.','Serve with tomato slices.']::text[], 4, 25, array['breakfast','lunch']::text[], null),
  ('ebf90059-f247-889f-4271-149f4957d136'::uuid, 'tzatziki', 'Τζατζίκι', 'Tzatziki', array['Τρίψτε το αγγούρι, αλατίστε το ελαφρά και στύψτε το καλά σε τουλπάνι να φύγουν τα υγρά.','Ανακατέψτε το γιαούρτι με το αγγούρι, το σκόρδο λιωμένο, το ξίδι και τον άνηθο.','Προσθέστε το ελαιόλαδο, ανακατέψτε και αφήστε το 30 λεπτά στο ψυγείο πριν σερβίρετε.']::text[], array['Grate the cucumber, salt it lightly and squeeze well in a cloth to remove the liquid.','Mix the yoghurt with the cucumber, crushed garlic, vinegar and dill.','Add the olive oil, stir and chill for 30 minutes before serving.']::text[], 4, 15, array['snack']::text[], null)
